insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-ovsyanka-yabloko', 'Овсяная каша с яблоком', 'Сладкая каша за 15 минут: яблоко и корица вместо варенья', 'breakfast', array['breakfast']::text[], 10, 15, 4, 1, 'dairy', array['быстро','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Яблоко Диме натереть или нарезать мелко', array['Хлопья залить молоком и соком, добавить сахар и поставить на средний огонь.','Довести до кипения, помешивая, убавить огонь и варить 5 минут.','Снять с огня, накрыть крышкой и оставить на 5–7 минут, чтобы каша загустела.','Яблоки очистить и нарезать тонкими ломтиками.','Добавить в кашу яблоки, корицу и сливки, перемешать и подавать.']::text[], 'https://www.gastronom.ru/recipe/2700/ovsyanaya-kasha-s-yablokom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
