insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-grechka-molochnaya', 'Гречневая каша с молоком', 'Молочная гречка, как в детстве: сытно и недорого', 'breakfast', array['breakfast']::text[], 10, 35, 4, 1, 'dairy', array['будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Соль и сахар класть по минимуму', array['Гречку перебрать и промыть до чистой воды.','Всыпать в кипящую подсоленную воду, накрыть и варить на самом слабом огне 20 минут.','Влить горячее молоко, добавить сахар и снова довести до кипения.','Положить масло, перемешать, накрыть и оставить на выключенной плите на 10–15 минут.']::text[], 'https://www.gastronom.ru/recipe/25608/grechnevaja-kasha-na-moloke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
