insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-mannaya', 'Манная каша', 'Каша за 10 минут без комочков: манку заливаем холодным молоком', 'breakfast', array['breakfast']::text[], 10, 15, 4, 1, 'dairy', array['быстро','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Можно подать с тёртым яблоком вместо сахара', array['Манку, сахар и соль насыпать в сотейник с толстым дном.','Тонкой струйкой влить холодное молоко, всё время размешивая венчиком.','Поставить на небольшой огонь и мешать, пока каша не закипит и не загустеет.','Поварить 2–3 минуты, не переставая мешать.','Снять с огня, накрыть на пару минут и подавать с маслом.']::text[], 'https://1000.menu/cooking/1102-kasha-mannaya', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
