insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-pshennaya-tykva', 'Пшённая каша с тыквой', 'Осенняя каша: тыква делает пшено сладким и ярким', 'breakfast', array['breakfast']::text[], 15, 40, 4, 2, 'dairy', array['будни','бюджетное']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Тыкву размять вилкой, сахар — по минимуму', array['Тыкву нарезать мелким кубиком, залить половиной молока и потушить 5–10 минут после закипания.','Пшено промыть несколько раз холодной, а затем горячей водой.','Добавить к тыкве пшено, соль и остальное молоко, довести до кипения.','Варить под крышкой на слабом огне около 25 минут.','Дать постоять несколько минут, положить масло, по вкусу сахар или мёд.']::text[], 'https://www.iamcook.ru/showrecipe/7892', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
