insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-risovaya-molochnaya', 'Рисовая каша на молоке', 'Нежная молочная каша, которую любят и малыши, и взрослые', 'breakfast', array['breakfast']::text[], 15, 40, 4, 2, 'dairy', array['будни','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Сахара в рецепте много: можно класть половину, взрослым досластить', array['Рис промыть в нескольких водах до прозрачности.','Вскипятить воду с солью, всыпать рис и варить под крышкой 10 минут.','Слить лишнюю воду, влить молоко, добавить сахар и ванильный сахар, довести до кипения.','Варить под крышкой на слабом огне около 12 минут, помешивая.','Выключить огонь, положить масло и дать каше постоять 10 минут.']::text[], 'https://www.gastronom.ru/recipe/58065/risovaja-kasha-na-moloke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
