insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-kukuruznaya', 'Кукурузная каша на молоке', 'Солнечная молочная каша из кукурузной крупы, без комков', 'breakfast', array['breakfast']::text[], 10, 25, 4, 1, 'dairy', array['быстро','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Каша без глютена, малышу подходит как есть', array['Молоко довести до кипения с солью и сахаром.','Тонкой струйкой всыпать крупу, сразу размешивая венчиком, чтобы не было комков.','Варить на слабом огне 15–20 минут, всё время помешивая, пока крупа не разварится и каша не загустеет.','Снять с огня, вмешать масло и подавать тёплой.']::text[], 'https://www.iamcook.ru/showrecipe/7853', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
