insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-kuskus', 'Каша из кускуса с яблоком', 'Самая быстрая каша: кускус почти не варится, сверху яблоко с изюмом', 'breakfast', array['breakfast']::text[], 15, 20, 4, 1, 'dairy', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Изюм Диме порезать мельче', array['Яблоко нарезать кубиками, изюм промыть тёплой водой.','В сковороде растопить масло, положить яблоки, изюм и половину сахара и потушить 3–4 минуты.','В кастрюлю с толстым дном влить молоко, всыпать кускус, оставшийся сахар и соль.','Варить на небольшом огне 5 минут, помешивая.','Выключить огонь и оставить под крышкой на 10 минут.','Разложить кашу по тарелкам, сверху выложить яблоки с изюмом.']::text[], 'https://1000.menu/cooking/34565-kasha-iz-kuskusa-s-molokom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
