insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-druzhba', 'Каша «Дружба»', 'Рис и пшено вместе — каша из садиковского меню', 'breakfast', array['breakfast']::text[], 25, 60, 4, 2, 'dairy', array['выходные','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Каша из садиковского меню, малышу как есть', array['Рис и пшено перебрать и промыть сначала тёплой, потом горячей водой.','Вскипятить воду, всыпать пшено и рис и варить на самом слабом огне около 10 минут, помешивая, пока вода не впитается.','Влить горячее молоко, посолить и добавить сахар.','Варить на маленьком огне до мягкости круп, около 25 минут, помешивая.','Заправить растопленным маслом.']::text[], 'https://menunedeli.ru/recipe/kasha-druzhba-kak-v-detskom-sadu/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
