insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-syrniki', 'Сырники', 'Сырники на всю семью за 20 минут', 'breakfast', array['breakfast','snack']::text[], 25, 25, 4, 2, 'cottage', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме 2–3 сырника не жарить, а запечь на бумаге в духовке: 180°, 15–20 минут', array['Яйца взбить с сахаром.','Творог протереть через сито или размять вилкой и смешать с яйцами.','Добавить манку, соду, ванильный сахар и муку, замесить густое тесто.','Мокрой ложкой набирать тесто, лепить лепёшки и обваливать в муке.','Жарить на разогретом масле на среднем огне по 3–4 минуты с каждой стороны до румяной корочки, затем 2–3 минуты под крышкой на слабом огне.','Выложить на салфетку и подавать со сметаной, вареньем или ягодами.']::text[], 'https://1000.menu/cooking/37190-prostye-syrniki-iz-tvoroga-na-skovorode', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
