insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-zapekanka-tvorozhnaya', 'Творожная запеканка', 'Запеканка как в садике: одна форма на два-три завтрака', 'breakfast', array['breakfast','snack','dinner']::text[], 15, 45, 4, 3, 'cottage', array['будни','духовка','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'ok', 'Изюм можно не класть или порезать мельче', array['Духовку разогреть до 180°. Творог растереть с мягким маслом.','Яйцо взбить с сахаром до пышной пены.','Соединить творог, яйцо, соль, ванильный сахар, изюм и манку, перемешать до однородности.','Форму смазать маслом и посыпать сухарями, выложить массу и смазать сверху сметаной.','Выпекать около 30 минут, пока верх не станет золотистым.']::text[], 'https://www.edimdoma.ru/retsepty/44250-tvorozhnaya-zapekanka-kak-v-detskom-sadu', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
