insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-lenivye-vareniki', 'Ленивые вареники', 'Вареники без лепки: творожное тесто режем и варим 2 минуты', 'breakfast', array['breakfast','dinner']::text[], 15, 20, 4, 1, 'cottage', array['быстро','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Варёное и мягкое — Диме как есть', array['Творог протереть через сито или пробить блендером, смешать с яйцом, сахаром и солью.','Понемногу добавлять муку, пока тесто не станет мягким и чуть липким.','Скатать колбаску толщиной 2–3 см и нарезать кусочками.','Опустить в кипящую подсоленную воду и варить 1–2 минуты после всплытия.','Вынуть шумовкой и подавать со сметаной.']::text[], 'https://www.gastronom.ru/recipe/66791/lenivye-vareniki-s-tvorogom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
