insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-tvorog-smetana-yagody', 'Творог со сметаной и ягодами', 'Завтрак без плиты за 5 минут', 'breakfast', array['breakfast','snack']::text[], 5, 10, 4, 1, 'cottage', array['быстро','без плиты','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Мёд — только если нет аллергии', array['Ягоды разморозить: с вечера в холодильнике или пару минут в микроволновке.','Творог перемешать со сметаной, при желании взбить блендером.','Разложить по тарелкам, сверху ягоды, полить мёдом по вкусу.']::text[], 'https://menunedeli.ru/2012/08/tvorog-so-smetanoj/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
