insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-tvorog-banan', 'Творог с бананом', 'Творожный крем с бананом из блендера — как десерт, но на завтрак', 'breakfast', array['breakfast','snack']::text[], 10, 15, 4, 1, 'cottage', array['быстро','без плиты','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме без орехов и печенья', array['Бананы, кроме одного, нарезать и пробить блендером в пюре.','Добавить творог, сметану и ванильный сахар и взбить до гладкости.','Подсластить мёдом и ещё раз взбить.','Оставшийся банан нарезать кружками, печенье и орехи раскрошить.','Разложить по стаканам слоями: крем, банан, крошка.']::text[], 'https://1000.menu/cooking/40300-tvorog-s-bananom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
