insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-buterbrody-tvorozhnaya-pasta', 'Бутерброды с творожной пастой и огурцом', 'Несладкий творог: паста с зеленью на хлеб, сверху огурец', 'breakfast', array['breakfast','snack']::text[], 10, 10, 4, 1, 'cottage', array['быстро','без плиты']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Порцию пасты Диме отложить до чеснока и перца', array['Творог размять вилкой, комковатый — пробить блендером.','Зелень вымыть, обсушить и мелко порубить.','Смешать творог с йогуртом до густой пасты, добавить зелень, соль и перец.','По желанию выдавить зубчик чеснока и перемешать.','Намазать пасту на хлеб, сверху положить ломтики огурца.']::text[], 'https://1000.menu/cooking/20107-tvorojnaya-pasta-s-zelenu-dlya-buterbrodov', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
