insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-omlet', 'Омлет', 'Пышный омлет на сковороде под крышкой', 'breakfast', array['breakfast','dinner']::text[], 10, 20, 4, 1, 'egg', array['быстро','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Готовить без корочки, под крышкой на слабом огне', array['Яйца с солью перемешать вилкой, не взбивая.','Добавить молоко и сметану и ещё раз перемешать.','Смазать сковороду маслом, прогреть на среднем огне и вылить смесь.','Готовить 2–3 минуты без крышки, приподнимая края лопаткой.','Накрыть крышкой и держать на слабом огне 5–7 минут, затем 5 минут под крышкой без огня. Посыпать рубленым укропом.']::text[], 'https://menunedeli.ru/recipe/recept-pyshnogo-omleta-na-skovorode-s-molokom/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
