insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-omlet-ovoshchi', 'Омлет с помидорами и перцем', 'Омлет, в котором уже есть овощи', 'breakfast', array['breakfast','dinner']::text[], 15, 20, 4, 1, 'egg', array['быстро']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит: овощи тушатся, перец только взрослым в тарелку.', array['Перец очистить от семян, нарезать кубиками и тушить на масле на небольшом огне 4–5 минут до мягкости.','Добавить нарезанные помидоры и прогреть 2–3 минуты, пока не дадут сок.','Яйца взбить с молоком и солью.','Залить овощи яичной смесью, накрыть крышкой и готовить 5–6 минут на малом огне.','Подавать сразу, посыпав зеленью. Взрослым поперчить в тарелке.']::text[], 'https://www.iamcook.ru/showrecipe/33854', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
