insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-yaichnica-pomidory', 'Яичница с помидорами и луком', 'Сытная яичница с овощами за 20 минут', 'breakfast', array['breakfast','dinner']::text[], 10, 20, 4, 1, 'egg', array['быстро','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'В маленькой сковороде потушить ему под крышкой ложку лука и помидоров с ложкой воды, залить 1–2 яйцами из общей миски и держать на огне, пока яйцо полностью не схватится.', array['Лук нарезать соломкой, помидоры — дольками.','Обжарить лук на масле 5 минут, добавить помидоры и готовить ещё 5–8 минут, один раз перевернув.','Яйца взбить с солью и вылить на овощи.','Накрыть крышкой и готовить на слабом огне около 7 минут.','Посыпать рубленой петрушкой и подавать. Взрослым поперчить в тарелке.']::text[], 'https://www.gastronom.ru/recipe/55915/jaichnica-s-pomidorami-i-lukom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
