insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-skrembl-syr', 'Болтунья с сыром', 'Нежная болтунья с сыром за 10 минут', 'breakfast', array['breakfast']::text[], 10, 15, 4, 1, 'egg', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его часть оставить на огне ещё 1–2 минуты, пока яйцо полностью не схватится.', array['Сыр натереть на средней тёрке.','Яйца перемешать с молоком и солью, добавить сыр.','Разогреть сковороду с маслом на среднем огне и вылить смесь.','Помешивать лопаткой, пока яйца не соберутся в нежные хлопья.','Снять с огня, пока болтунья чуть влажная, и сразу подавать.']::text[], 'https://1000.menu/cooking/88589-skrembl-s-syrom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
