insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-omlet-sadik', 'Высокий омлет в духовке, как в садике', 'Высокий омлет из духовки, как в детском саду, без жарки', 'breakfast', array['breakfast','dinner']::text[], 10, 35, 4, 1, 'egg', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Омлет из духовки малышу подходит как есть', array['Духовку разогреть до 200°. Яйца перемешать вилкой, не взбивая в пену.','Влить холодное молоко, посолить и снова перемешать.','Форму смазать маслом и вылить смесь: она должна занять больше половины формы.','Выпекать около 20 минут, духовку не открывать.','Смазать горячий омлет маслом, дать немного остыть и нарезать.']::text[], 'https://www.gastronom.ru/recipe/46675/pyshnyj-omlet-kak-v-detskom-sadike', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
