insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-yaytsa-vsmyatku-grenki', 'Яйца всмятку с гренками', 'Яйцо всмятку и хрустящий хлеб — завтрак за 10 минут', 'breakfast', array['breakfast']::text[], 5, 12, 4, 0, 'egg', array['быстро','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме яйцо сварить вкрутую, 8–10 минут: жидкий желток малышу лучше не давать', array['Яйца заранее достать из холодильника, чтобы не треснули.','Вскипятить воду, посолить и опустить яйца ложкой.','Варить 4 минуты после закипания, затем переложить в холодную воду.','Пока варятся яйца, подсушить хлеб на сухой сковороде или в тостере, смазать маслом и нарезать брусочками.','Срезать верхушку яйца и подавать с гренками.']::text[], 'https://menunedeli.ru/recipe/yajca-vsmyatku-kak-pravilno-i-skolko-varit-posle-zakipaniya-vody/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
