insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-bliny', 'Блины на молоке', 'Тонкие блины на выходные: к сметане, варенью или творогу', 'breakfast', array['breakfast','snack']::text[], 35, 40, 4, 2, 'dairy', array['выходные','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Печь на сухой антипригарной сковороде; Диме 1–2 мягких блина без поджаристых краёв, с творогом или сметаной', array['Продукты заранее достать, чтобы были комнатной температуры.','Смешать молоко, соль, сахар, растительное масло и яйца, взбить до однородности.','Просеять муку и вмешать до жидкого теста без комков.','Сковороду хорошо разогреть и смазать маслом.','Налить половник теста, быстро распределить по дну, печь до румяных краёв и перевернуть.','Горячие блины по желанию смазать сливочным маслом.']::text[], 'https://www.iamcook.ru/showrecipe/14007', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
