insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-oladi-kefir', 'Оладьи на кефире', 'Пышные оладьи из самых простых продуктов', 'breakfast', array['breakfast','snack']::text[], 20, 30, 4, 1, 'dairy', array['будни','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме испечь оладьи в духовке на бумаге: 200°, 10–12 минут', array['Кефир согреть до комнатной температуры и смешать с яйцом и сахаром.','Всыпать просеянную муку с содой, перемешать и оставить тесто на 15 минут.','Разогреть масло на сковороде и выкладывать тесто ложкой.','Жарить на умеренном огне до румяности с обеих сторон.','Выложить на бумажное полотенце, подавать с мёдом, сметаной или вареньем.']::text[], 'https://www.edimdoma.ru/retsepty/143647-pyshnye-oladi', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
