insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-oladi-kabachki', 'Оладьи из кабачков', 'Овощи на завтрак, которые дети едят охотно', 'breakfast', array['breakfast','snack','dinner']::text[], 20, 25, 4, 1, 'egg', array['быстро','детское','бюджетное']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Диме испечь оладьи в духовке на бумаге: 180°, 15–20 минут, перевернуть на середине', array['Кабачок вымыть, обрезать концы и натереть на мелкой тёрке.','Хорошо отжать лишнюю воду.','Добавить яйцо, муку, сметану, соль и сахар, перемешать и дать постоять 5 минут.','Смазать сковороду маслом и выкладывать тесто по столовой ложке.','Жарить на тихом огне по 2–3 минуты с каждой стороны до лёгкого румянца.','Подавать со сметаной.']::text[], 'https://www.iamcook.ru/showrecipe/15606', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
