insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-oladi-banan', 'Банановые оладьи', 'Перезревший банан пойдёт в дело: пышные сладкие оладьи', 'breakfast', array['breakfast','snack']::text[], 20, 20, 4, 1, 'egg', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме испечь в духовке на бумаге: 200°, 10–12 минут; это сладкое — в счёт 2–3 раз в неделю', array['Банан размять вилкой в пюре и растереть с сахаром.','Добавить яйца, кефир и соль и слегка взбить.','Просеять муку с разрыхлителем и перемешать до теста густотой как сметана.','Жарить на разогретой сковороде с минимумом масла по 2 минуты с каждой стороны.','Подавать с йогуртом или мёдом.']::text[], 'https://www.edimdoma.ru/retsepty/52187-bananovye-pankeyki', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
