insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-draniki', 'Драники', 'Картофельные драники на выходной завтрак, со сметаной', 'breakfast', array['breakfast','dinner']::text[], 30, 40, 4, 1, 'none', array['выходные','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его драники из отложенной массы запечь на бумаге в духовке: 200 °C, 20 минут, перевернуть на середине.', array['Картофель и лук очистить, натереть на тёрке и отжать лишний сок.','Добавить яйцо, муку и соль, перемешать. Отложить Диме 4–5 ложек массы, остальное поперчить.','Разогреть масло, выкладывать массу ложкой и слегка разравнивать.','Жарить на среднем огне по 3–4 минуты с каждой стороны до корочки.','Подавать горячими со сметаной.']::text[], 'https://1000.menu/cooking/3943-draniki-kartofelnye-klassicheskie', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
