insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-ovsyanoblin', 'Овсяноблин с сыром', 'Блин из овсянки и яйца с сыром внутри — сытно и быстро', 'breakfast', array['breakfast']::text[], 20, 25, 4, 0, 'egg', array['быстро']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме то же тесто запечь в формочке: 180°, 10–12 минут', array['Хлопья смолоть блендером в крупную муку.','Залить молоком, вбить яйца и взбить венчиком до однородности.','Разогреть антипригарную сковороду, при необходимости смазать каплей масла, вылить четверть теста.','Печь 2–3 минуты и перевернуть.','На половину блина выложить сыр и банан, накрыть крышкой на минуту, сложить пополам и подержать ещё минуту.','Так же испечь остальные блины.']::text[], 'https://menunedeli.ru/recipe/ovsyanoblin/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
