insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-grenki-sladkie', 'Сладкие гренки', 'Гренки из вчерашнего батона, яйца и молока', 'breakfast', array['breakfast','snack']::text[], 15, 20, 4, 0, 'egg', array['быстро','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме гренку запечь в духовке: 180°, 10 минут; это сладкое — в счёт 2–3 раз в неделю', array['Яйца смешать с молоком и сахаром, по желанию добавить корицу и слегка взбить.','Каждый ломтик батона быстро обмакнуть в смесь с двух сторон.','Обжарить на прогретой сковороде с маслом по минуте с каждой стороны.','Подавать с вареньем, мёдом или сгущёнкой.']::text[], 'https://www.iamcook.ru/showrecipe/12195', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
