insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-buterbrody-goryachie', 'Горячие бутерброды с сыром и помидором', 'Бутерброды из духовки: сыр, помидор, укроп', 'breakfast', array['breakfast','snack']::text[], 10, 25, 4, 0, 'dairy', array['быстро','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме отдельный бутерброд: хлеб, помидор и твёрдый сыр, без майонеза и плавленого сыра', array['Плавленый сыр подержать 15 минут в морозилке, чтобы легче натирался. Духовку разогреть до 200°.','Натереть оба сыра, укроп мелко порубить.','Смешать плавленый сыр с укропом и майонезом.','Хлеб нарезать, смазать сырной массой и положить кружки помидора.','Посыпать твёрдым сыром и запекать около 15 минут, пока сыр не расплавится.']::text[], 'https://1000.menu/cooking/23393-buterbrody-s-pomidorami-i-syrom-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
