insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-buterbrody-yaytso-ogurets', 'Бутерброды с яйцом и огурцом', 'Яичная намазка и свежий огурец на хрустящем хлебе', 'breakfast', array['breakfast','snack']::text[], 15, 20, 4, 0, 'egg', array['быстро','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'До чеснока натереть ему одно яйцо отдельно и смешать с ложкой сметаны вместо майонеза.', array['Яйца сварить вкрутую, 12 минут, и остудить в холодной воде.','Батон нарезать и подсушить в тостере, духовке или на сухой сковороде.','Яйца очистить и натереть на мелкой тёрке вместе с чесноком.','Смешать с майонезом.','Намазать хлеб яичной массой, сверху выложить тонкие ломтики огурца.']::text[], 'https://iamcook.ru/showrecipe/36500', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
