insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('br-granola-yogurt', 'Домашняя гранола с йогуртом', 'Печём гранолу раз в две недели, утром — йогурт и горсть хлопьев', 'breakfast', array['breakfast','snack']::text[], 15, 45, 8, 14, 'dairy', array['выходные','духовка','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме гранолу без орехов (часть отсыпать до орехов) или орехи смолоть в крошку; мёд — в счёт сладкого', array['Духовку разогреть до 140°. Орехи порубить ножом, изюм промыть и обсушить.','Хлопья перемешать руками с орехами, мёдом и маслом, чтобы получились комочки.','Выложить на противень с бумагой и запекать 30–35 минут, перемешивая каждые 7–8 минут.','За 5 минут до конца добавить изюм.','Остудить и хранить в банке с крышкой до двух недель.','Утром насыпать гранолу в тарелку и залить йогуртом.']::text[], 'https://menunedeli.ru/recipe/domashnyaya-granola/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
