insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-yabloki-tvorog', 'Печёные яблоки с творогом', 'Печёное яблоко с творогом: полдник без муки и почти без сахара', 'snack', array['snack','breakfast']::text[], 10, 40, 4, 1, 'cottage', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Яблоко Диме дать без кожуры', array['Духовку разогреть до 200°. Творог протереть через сито или пробить блендером.','Желток растереть с сахаром и ванильным сахаром и смешать с творогом.','У яблок срезать верхушку-крышечку, ложкой вынуть сердцевину, бока наколоть вилкой.','Наполнить яблоки творогом и накрыть крышечками.','Запекать 20–25 минут, пока яблоки не станут мягкими, а кожица не начнёт лопаться.']::text[], 'https://www.gastronom.ru/recipe/27449/jabloki-s-tvorogom-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
