insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-sharlotka', 'Шарлотка', 'Классика из трёх яиц, стакана муки и стакана сахара', 'dessert', array['snack']::text[], 20, 50, 8, 3, 'egg', array['духовка','выходные','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшую порцию и не чаще 2–3 раз в неделю вместе с другими сладостями', array['Духовку разогреть до 190°. Яйца взбить с сахаром миксером до светлой пышной массы.','Муку просеять с содой и ванильным сахаром и вмешать в яйца.','Яблоки разрезать, удалить сердцевину и нарезать ломтиками.','Смешать яблоки с тестом и переложить в смазанную маслом форму.','Выпекать 30 минут, готовность проверить деревянной шпажкой.']::text[], 'https://www.gastronom.ru/recipe/24208/klassicheskaja-sharlotka-s-jablokami', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
