insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-keks-tvorozhny', 'Творожный кекс с изюмом', 'Влажный кекс на твороге: три-четыре дня остаётся мягким', 'dessert', array['snack','breakfast']::text[], 20, 75, 8, 4, 'cottage', array['духовка','выходные','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшую порцию и не чаще 2–3 раз в неделю вместе с другими сладостями', array['Изюм промыть и замочить в тёплой воде на 15 минут, затем обсушить.','Духовку разогреть до 170°. Яйца взбить с сахаром и добавить творог.','Понемногу вмешать муку с разрыхлителем.','Добавить изюм и тёртую лимонную цедру.','Выложить в смазанную маслом форму и печь 40–50 минут до сухой шпажки.','Остудить 10 минут в форме, затем на решётке.']::text[], 'https://www.gastronom.ru/recipe/41476/tvorozhnyj-keks-s-izyumom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
