insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-maffiny-banan', 'Банановые маффины', 'Маффины на спелых бананах, 12 штук на несколько полдников', 'dessert', array['snack','breakfast']::text[], 20, 60, 12, 3, 'egg', array['духовка','выходные','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме один маффин, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Масло заранее достать, духовку разогреть до 180°.','Мягкое масло взбить с сахаром до светлой пышной массы.','По одному добавить яйца, каждый раз перемешивая.','Бананы натереть на тёрке прямо перед добавлением и вмешать в тесто.','Муку просеять с разрыхлителем, солью и ванильным сахаром и вмешать в три приёма.','Разложить тесто по формочкам на 2/3 и печь около 25 минут до золотистого цвета.']::text[], 'https://1000.menu/cooking/12209-bananovye-maffiny', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
