insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-pechenye-ovsyanoe', 'Овсяное печенье', 'Простое печенье из продуктов, которые всегда есть дома', 'dessert', array['snack']::text[], 10, 40, 4, 7, 'none', array['будни','духовка','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме одно печенье, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Духовку разогреть до 180°. Хлопья немного измельчить блендером.','Яйцо смешать с сахаром и солью, добавить масло, соду и лимонный сок.','Всыпать хлопья и понемногу вмешивать муку, пока тесто не станет вязким и не будет держать форму.','Скатать 8 шариков и приплюснуть.','Выпекать на бумаге около 30 минут, до лёгкого румянца снизу.']::text[], 'https://1000.menu/cooking/17012-ovsyanoe-pechene-proshche-prostogo', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
