insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-mannik', 'Манник на кефире', 'Пирог без муки: тесто замешивается за 10 минут', 'dessert', array['snack']::text[], 15, 90, 6, 3, 'dairy', array['духовка','выходные','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшую порцию и не чаще 2–3 раз в неделю вместе с другими сладостями', array['Смешать манку, сахар, ванильный сахар, соль и соду.','Добавить мягкое масло и яйцо и растереть руками в крошку.','Влить кефир комнатной температуры, перемешать до гладкости и оставить на 15–20 минут.','Духовку разогреть до 180°, форму смазать маслом.','Вылить тесто и печь 40–50 минут до сухой зубочистки.','Остудить в форме и только потом доставать.']::text[], 'https://menunedeli.ru/recipe/mannik-na-kefire-recept-1-stakan/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
