insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-fruktovy-salat', 'Фруктовый салат с йогуртом', 'Фрукты кубиками с йогуртом — полдник за 15 минут', 'snack', array['snack','breakfast']::text[], 15, 15, 4, 0, 'dairy', array['быстро','без плиты','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме нарезать мельче, виноград — на четвертинки, яблоко без кожуры', array['Фрукты вымыть и обсушить.','Банан нарезать кубиками, апельсин почистить, снять плёнки с долек и порезать.','Яблоки и грушу нарезать кубиками, виноградины разрезать.','Сложить всё в миску, полить мёдом и йогуртом и аккуратно перемешать.','Разложить по креманкам и сразу подавать.']::text[], 'https://www.iamcook.ru/showrecipe/15901', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
