insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-smuzi-banan-kefir', 'Смузи банан-кефир', 'Банан и кефир в блендере — полдник за 5 минут', 'snack', array['snack','breakfast']::text[], 5, 5, 4, 0, 'dairy', array['быстро','без плиты','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме полстакана; мёд — если нет аллергии', array['Бананы очистить, нарезать и сложить в блендер.','Влить кефир, добавить мёд и щепотку корицы.','Взбить до однородности и сразу разлить по стаканам.']::text[], 'https://www.gastronom.ru/recipe/60453/smuzi-iz-banana-i-kefira', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
