insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-vatrushki', 'Ватрушки с творогом', 'Дрожжевые ватрушки по садиковской рецептуре', 'dessert', array['snack','breakfast']::text[], 30, 210, 15, 3, 'cottage', array['духовка','выходные','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме одну ватрушку, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Дрожжи развести в тёплой воде, смешать с частью молока и муки и оставить опару в тепле на 1,5–2 часа.','Добавить яйцо, сахар, соль, остальное молоко и муку, вмешать растопленное масло в два приёма.','Дать тесту подняться вдвое, один-два раза обмяв.','Разделить на 15 шариков, выложить на противень и оставить на 15 минут. Духовку разогреть до 200°.','Творог растереть с яйцом, мукой, сахаром и ванильным сахаром.','Донышком стакана сделать в каждом шарике углубление и положить начинку.','Смазать взбитым яйцом и выпекать около 10 минут до румяной корочки.']::text[], 'https://menunedeli.ru/recipe/vatrushka-s-tvorogom-iz-drozhzhevogo-testa-kak-v-detskom-sadu/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
