insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-pirozhki-yabloko', 'Пирожки с яблоками в духовке', 'Пышные пирожки из духовки с тушёными яблоками и корицей', 'dessert', array['snack']::text[], 40, 120, 10, 3, 'none', array['духовка','выходные','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме один пирожок, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Дрожжи развести в тёплом молоке (около 35°) и оставить на 15 минут.','Яйца взбить с 50 г сахара и солью, половину масла растопить; влить яйца и половину муки в молоко с дрожжами.','Добавить остальную муку и масло, вымесить гладкое тесто и оставить в тепле на час.','Обмять тесто и дать подняться ещё 40 минут.','Тем временем яблоки нарезать кубиками, потушить 10 минут с маслом и сахаром, добавить корицу и остудить.','Разделить тесто на шарики, раскатать, положить начинку и защипнуть края.','Выложить швом вниз на бумагу и печь 15–20 минут при 190°.']::text[], 'https://www.gastronom.ru/recipe/31763/pirozhki-s-jablokami-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
