insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-gusinye-lapki', 'Творожное печенье «Гусиные лапки»', 'Творожное печенье с сахарной корочкой — лепить можно с детьми', 'dessert', array['snack']::text[], 25, 40, 8, 5, 'cottage', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшую порцию и не чаще 2–3 раз в неделю вместе с другими сладостями', array['Мягкое масло растереть с творогом.','Добавить ванильный сахар, разрыхлитель и половину муки и замесить.','Вымесить на столе с остальной мукой до эластичности.','Тонко раскатать и вырезать стаканом кружки.','Посыпать кружок сахаром, сложить пополам, снова посыпать и сложить треугольником.','Выложить на противень с бумагой и печь 15–20 минут при 180°.']::text[], 'https://www.gastronom.ru/recipe/62169/tvorozhnoe-pechene-gusinye-lapki', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
