insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-risovaya-zapekanka', 'Рисовая запеканка с яблоками', 'Рис, яблоки и яйцо — простая запеканка на полдник', 'snack', array['snack','breakfast']::text[], 15, 40, 4, 2, 'egg', array['будни','духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Запеканка из садиковского меню, малышу как есть', array['Рис отварить в подсоленной воде до полуготовности и откинуть на дуршлаг.','Яблоки без сердцевины нарезать брусочками.','Смешать рис, яблоки и мягкое масло.','Яйца взбить с сахаром.','Выложить рис в смазанную форму и залить яйцами.','Запекать 20–25 минут при 180°, по желанию посыпать корицей.']::text[], 'https://menunedeli.ru/recipe/risovaya-zapekanka-s-yablokami/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
