insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-zhele-yagodnoe', 'Ягодное желе', 'Желе из замороженных ягод: 20 минут работы, остальное — холодильник', 'dessert', array['snack']::text[], 20, 200, 4, 3, 'none', array['детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшую порцию и не чаще 2–3 раз в неделю вместе с другими сладостями', array['Желатин замочить в половине стакана холодной воды по инструкции на упаковке, затем растворить на водяной бане, не кипятя.','Ягоды раздавить, залить остальной водой с сахаром, довести до кипения и процедить; часть ягод можно оставить целыми.','Смешать горячий морс с желатином.','Разлить по креманкам, остудить и убрать в холодильник на 3 часа.']::text[], 'https://www.iamcook.ru/showrecipe/5188', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
