insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-keks-morkovny', 'Морковный кекс', 'Кекс с тёртой морковью: сочный, яркий и недорогой', 'dessert', array['snack','breakfast']::text[], 20, 70, 8, 4, 'egg', array['духовка','выходные','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме небольшую порцию и не чаще 2–3 раз в неделю вместе с другими сладостями', array['Духовку разогреть до 180°. Морковь натереть на мелкой тёрке.','Яйца взбить с сахаром и солью до пены.','Добавить морковь, ванильный сахар и масло и перемешать лопаткой.','Просеять муку с разрыхлителем и аккуратно вмешать.','Выложить в смазанную форму и печь 40–50 минут до сухой зубочистки.','Остудить в форме, накрыв полотенцем.']::text[], 'https://www.iamcook.ru/showrecipe/32805', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
