insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-sochniki', 'Сочники с творогом', 'Сочники из песочного теста, как в советской булочной', 'dessert', array['snack']::text[], 35, 75, 7, 3, 'cottage', array['духовка','выходные','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое: Диме один сочник, не чаще 2–3 раз в неделю вместе с другими сладостями', array['Для начинки смешать творог, сахар, ложку сметаны, половину белка и немного муки до густоты.','Муку просеять и перемешать с солью и содой.','Мягкое масло взбить с сахаром, добавить яйцо и сметану.','Всыпать мучную смесь и быстро замесить тесто.','Раскатать пласт толщиной 5 мм и вырезать кружки 8–10 см.','Положить на каждый кружок ложку начинки ближе к краю и прикрыть второй половиной, не защипывая.','Смазать желтком и печь 20–25 минут при 180°.']::text[], 'https://www.gastronom.ru/recipe/31204/sochniki-s-tvorogom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
