insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ds-zebra', 'Пирог «Зебра»', 'Полосатый пирог на сметане, который любят дети', 'dessert', array['snack']::text[], 25, 75, 10, 3, 'egg', array['духовка','выходные','праздничное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Сладкое, в тесте какао: Диме небольшой кусок не чаще раза в неделю, в счёт сладкого', array['Духовку разогреть до 180°. Мягкое масло растереть с половиной сахара.','По одному вбить яйца, понемногу досыпая остальной сахар, и взбить до пышности.','Добавить сметану, соль, разрыхлитель и ванильный сахар, затем вмешать просеянную муку.','Разделить тесто пополам и в одну часть добавить какао.','Выкладывать в форму 20–22 см по две ложки, чередуя светлое и тёмное тесто, и провести узор зубочисткой.','Печь 40–50 минут до сухой зубочистки и остудить в форме.']::text[], 'https://www.iamcook.ru/showrecipe/7309', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
