insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-tykva-yabloki', 'Тыква, запечённая с яблоком', 'Тыква с яблоком и мёдом из духовки — тёплый осенний полдник', 'snack', array['snack']::text[], 15, 60, 4, 2, 'none', array['духовка','детское','постное','бюджетное']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Тыкву и яблоко размять, изюм порезать; мёд — если нет аллергии', array['Духовку разогреть до 180°. Очень сухой изюм замочить на 10–15 минут.','Тыкву очистить от кожуры и семечек, яблоки — от сердцевины и нарезать мелким кубиком.','Перемешать с изюмом и разложить по формочкам или в одну форму.','Посыпать корицей, полить мёдом, по желанию добавить ложку воды.','Запекать до мягкости тыквы, около 40 минут, подавать тёплым.']::text[], 'https://www.iamcook.ru/showrecipe/33996', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
