insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sn-pechenye-syrnoe', 'Сырное печенье', 'Несладкое печенье на полдник — сыр вместо сахара', 'snack', array['snack']::text[], 25, 60, 6, 5, 'dairy', array['духовка','выходные','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Сыр брать неострый, соль — по минимуму', array['Масло заранее размягчить, сыр натереть на средней тёрке.','Смешать сыр, масло, желток и соль.','Понемногу добавить муку, замесить мягкое тесто и убрать в холодильник на 30 минут.','Раскатать тесто между листами бумаги в 2–3 мм и нарезать фигурками.','Выпекать 15 минут при 180° до румяности и дать полностью остыть.']::text[], 'https://1000.menu/cooking/7781-francuzskoe-syrnoe-pechene', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
