insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-kompot-suhofrukty', 'Компот из сухофруктов', 'Компот как в садике, кастрюля на два-три дня', 'drink', array['lunch','snack','dinner']::text[], 10, 45, 10, 3, 'none', array['будни','бюджетное','постное','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'ok', 'Компот из садиковского меню; сахар можно уменьшить', array['Сухофрукты промыть в нескольких водах.','Сахар засыпать в воду и довести до кипения.','Закладывать по очереди: груши на 5 минут, затем яблоки, чернослив и курагу ещё на 10 минут.','Добавить изюм, довести до кипения и выключить огонь.','Накрыть крышкой и дать остыть, можно настоять на ночь.']::text[], 'https://menunedeli.ru/recipe/kompot-iz-smesi-suxofruktov-kak-v-detskom-sadu/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
