insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-kompot-yagody', 'Компот из замороженных ягод', 'Ягоды прямо из морозилки, без разморозки', 'drink', array['lunch','snack','dinner']::text[], 5, 45, 8, 2, 'none', array['будни','бюджетное','постное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме — тёплый или комнатной температуры', array['Воду довести до кипения.','Опустить ягоды, не размораживая.','Когда снова закипит, убавить огонь до среднего и добавить сахар по вкусу.','Варить 3–5 минут.','Накрыть крышкой и настоять около 30 минут.']::text[], 'https://menunedeli.ru/2012/07/zamorozhennye-yagody-dlya-kompota-recept-s-foto/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
