insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-kisel-yagodny', 'Кисель ягодный', 'Ягодный кисель на крахмале за 20 минут', 'drink', array['snack','lunch']::text[], 15, 20, 6, 2, 'none', array['быстро','бюджетное','постное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Диме — тёплый, не горячий', array['Ягоды залить 250 мл воды, накрыть и довести до кипения на сильном огне.','Пробить блендером и протереть через сито.','Влить 1,5 л кипятка, добавить сахар и снова довести до кипения.','Крахмал развести в 200 мл холодной кипячёной воды и тонкой струйкой влить в кастрюлю, помешивая.','Прогреть 1–2 минуты до загустения и разлить по чашкам.']::text[], 'https://www.gastronom.ru/recipe/56128/yagodnyj-kisel-iz-zamorozhennyh-yagod', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
