insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-mors-klyukvenny', 'Морс клюквенный', 'Клюквенный морс: сок не кипятим, витамины остаются', 'drink', array['lunch','snack','dinner']::text[], 15, 55, 6, 3, 'none', array['постное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Морс кислый: Диме можно разбавить водой', array['Клюкву достать из морозилки за полчаса до начала.','Протереть ягоды через сито ложкой, пюре отложить.','Жмых из сита сложить в кастрюлю, добавить сахар и воду.','Нагреть до 60–70°, чтобы сахар растворился, не кипятить, и остудить.','Процедить остывший отвар на пюре и перемешать.','Подавать комнатной температуры или охлаждённым.']::text[], 'https://menunedeli.ru/recipe/klyukvennyj-mors-iz-zamorozhennoj-klyukvy/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
