insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-kakao', 'Какао на молоке', 'Какао с пенкой, как в детстве', 'drink', array['breakfast','snack']::text[], 15, 15, 4, 0, 'dairy', array['быстро','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Какао близко к шоколаду: Диме некрепкое, пополам с молоком, раз-два в неделю в счёт сладкого', array['Какао смешать с сахаром, развести тёплой водой и прогреть почти до кипения, помешивая.','Молоко подогреть и влить в какао-пасту.','Довести до первых пузырьков и снять с огня.','Взбить венчиком 20–30 секунд до пенки и разлить по чашкам.']::text[], 'https://www.gastronom.ru/recipe/27560/klassicheskoe-kakao', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
