insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('dr-moloko-myod', 'Тёплое молоко с мёдом', 'Тёплое молоко с ложкой мёда перед сном', 'drink', array['snack','dinner']::text[], 5, 15, 4, 0, 'dairy', array['быстро']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме полстакана и чайную ложку мёда, если нет аллергии', array['Молоко довести до кипения.','Дать остыть минут 10, чтобы стало тёплым, а не горячим.','Разлить по стаканам и в каждом размешать ложку мёда.']::text[], 'https://www.gastronom.ru/text/moloko-s-medom-polza-i-vred-neozhidannie-fakti-i-soveti-po-primeneniu-1018017', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
