insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-pelmeni', 'Пельмени домашние', 'Лепим всей семьёй за столом, а лишние уходят в морозилку про запас', 'main', array['lunch','dinner']::text[], 90, 150, 6, 1, 'red-meat', array['выходные','детское']::text[], array['any']::text[], array['weekend']::text[], 'adapt', 'Отложить ему часть фарша до перца и слепить пельмени отдельно, давать разрезанными пополам.', array['Лук прокрутить вместе с фаршем, посолить, поперчить и, вымешивая, понемногу влить 80 мл холодной воды. Убрать фарш в холодильник на час.','Яйца смешать с водой так, чтобы вышло 250 мл, слегка посолить. Вмешать в муку и вымешивать тесто около 15 минут до гладкости.','Накрыть тесто миской и оставить на 30 минут.','Раскатать тесто тонко, вырезать стаканом кружки около 5 см, на каждый положить чайную ложку фарша и защипнуть края.','Варить порциями в большой кастрюле подсоленной воды 5 минут после всплытия.','Подавать со сливочным маслом или сметаной. Лишние пельмени заморозить на доске, потом ссыпать в пакет.']::text[], 'https://www.gastronom.ru/recipe/4641/pelmeni-klassicheskie', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
