insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-vareniki-vishnya', 'Вареники с вишней', 'Кисло-сладкая вишня в тонком тесте и тёплый соус из сока со сметаной', 'dessert', array['lunch','dinner','snack']::text[], 75, 90, 4, 1, 'none', array['выходные','детское']::text[], array['any']::text[], array['weekend']::text[], 'adapt', 'Проверить вишню на косточки, вареник порезать. Сладкое — не чаще 2–3 раз в неделю.', array['Вишню разморозить на сите над миской, сок сохранить для соуса.','Замесить тесто из муки, яйца, кефира, щепотки соли и сахара, в конце добавить растительное масло. Накрыть плёнкой на 20–30 минут.','Раскатать тесто тонко, около 2 мм, и вырезать стаканом кружки.','На каждый кружок положить 3–4 вишни и щепотку сахара, края плотно защипнуть.','Варить в подсоленном кипятке 3–4 минуты после всплытия.','Для соуса вскипятить вишнёвый сок со сливочным маслом и 2–3 ложками сахара, снять с огня и вмешать сметану. Полить вареники.']::text[], 'https://menunedeli.ru/recipe/vareniki-s-zamorozhennoj-vishnej/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
