insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-manty', 'Манты', 'Сочный фарш с горой лука, приготовленный на пару, — едят руками со сметаной', 'main', array['lunch','dinner']::text[], 55, 100, 4, 2, 'red-meat', array['выходные']::text[], array['any']::text[], array['weekend']::text[], 'adapt', 'Отложить ему часть фарша до перца, давать разрезанными, со сметаной.', array['Замесить мягкое тесто из муки, 250 мл воды комнатной температуры, яйца и соли. Оставить под полотенцем на 15 минут.','Лук мелко нарезать, смешать с фаршем, посолить и поперчить.','Раскатать кусочки теста в тонкие круги, положить по столовой ложке начинки и защипнуть края.','В нижнюю часть мантоварки или пароварки налить воду, положить лавровый лист и довести до кипения.','Смазать ярусы маслом, разложить манты с промежутками и готовить под крышкой на среднем огне 40 минут. Подавать со сметаной.']::text[], 'https://www.edimdoma.ru/retsepty/108500-manty-s-govyazhim-farshem', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
