insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-hachapuri-adzharskie', 'Хачапури по-аджарски', 'Сырная лодочка с желтком: отрываешь корочку и макаешь в середину', 'main', array['breakfast','lunch','dinner']::text[], 40, 150, 4, 1, 'dairy', array['выходные','духовка']::text[], array['any']::text[], array['weekend']::text[], 'adapt', 'Его лодочку допечь 5–6 минут, до плотного желтка. Дать четвертинку: сулугуни солёный.', array['Молоко подогреть до тёплого, растворить в нём сахар и дрожжи, оставить на 15 минут.','Добавить соль, одно яйцо и муку, замесить упругое тесто. Дать подняться час, обмять и оставить ещё на 30–40 минут.','Разделить тесто на 4 части и растянуть каждую в овальную лепёшку. Сулугуни натереть и разложить по лепёшкам.','Завернуть длинные края к центру и защипнуть концы, чтобы вышли лодочки. Края смазать взбитым яйцом.','Печь 10–12 минут при 240 °C.','Вбить в середину каждой лодочки яйцо, допечь 2–3 минуты, положить кусочек масла и сразу подавать.']::text[], 'https://www.gastronom.ru/recipe/8145/hachapuri-po-adzharski-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
