insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-pirog-kurica-kartofel', 'Пирог с курицей и картошкой', 'Закрытый пирог: внутри курица с луком и картошка соломкой', 'main', array['lunch','dinner']::text[], 45, 105, 6, 2, 'poultry', array['выходные','духовка','на 2–3 дня']::text[], array['any']::text[], array['weekend']::text[], 'adapt', 'Начинку не перчить, взрослым поперчить в тарелке. Диме кусок без жёсткого края.', array['Сбить в блендере муку, мягкое масло, 3 яйца, кефир, сахар, соду и щепотку соли. Скатать шар, завернуть в плёнку и убрать в холодильник на 30 минут.','Картофель нарезать соломкой, филе — тонкими ломтиками, лук — мелко.','Курицу с луком обжарить на половине масла около 10 минут на слабом огне, картофель — на остальном масле ещё 10 минут. Остудить.','Разделить тесто на две части, большую раскатать и уложить в форму 24 см с бортиками.','Выложить курицу с луком, посолить, посыпать петрушкой, сверху распределить картофель и слегка посолить.','Накрыть второй лепёшкой, защипнуть края, сделать дырочку для пара и смазать взбитым яйцом. Печь около 40 минут при 190 °C, дать немного остыть.']::text[], 'https://www.gastronom.ru/recipe/59293/pirog-s-kuricej-i-kartoshkoj-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
