insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-pizza-margarita', 'Пицца «Маргарита»', 'Своё тесто, соус из свежих помидоров и тянущаяся моцарелла', 'main', array['lunch','dinner']::text[], 25, 60, 2, 1, 'dairy', array['выходные','духовка','детское']::text[], array['any']::text[], array['weekend']::text[], 'adapt', 'Его кусок не перчить и не посыпать пармезаном.', array['Смешать 75 мл тёплой воды, молоко, соль и дрожжи, всыпать муку, добавить ложку масла и вымесить тесто. Оставить в тепле на 40 минут.','Помидоры ошпарить, снять кожицу и измельчить. Обжарить на ложке масла 3 минуты, добавить томатную пасту, давленый чеснок и базилик, снять с огня.','Раскатать тесто чуть больше формы, переложить в форму, прижать края и наколоть вилкой.','Намазать соус, отступив от края 1,5–2 см, и печь 5 минут при 250 °C.','Разложить кружки моцареллы и печь ещё 2 минуты. Посыпать тёртым сыром и перцем.']::text[], 'https://www.gastronom.ru/recipe/18638/picca-margarita', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
