insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-pirozhki-kapusta', 'Пирожки с капустой в духовке', 'Пышные пирожки с капустой, яйцом и укропом — на обед, в школу, в дорогу', 'snack', array['lunch','snack']::text[], 80, 180, 8, 3, 'egg', array['выходные','духовка','на 2–3 дня','бюджетное']::text[], array['any']::text[], array['weekend']::text[], 'ok', 'Половинку пирожка: начинка мягкая.', array['Дрожжи развести в 50 мл тёплой воды с ложкой сахара и ложкой муки, оставить на 15 минут.','Смешать муку, остальной сахар, соль, тёплое молоко, растопленное масло и опару. Вымесить гладкое тесто, смазать растительным маслом и убрать в тепло на час.','Капусту нашинковать, ошпарить кипятком, отжать и обжарить на сливочном масле. Посолить, добавить рубленый укроп и мелко порубленные варёные яйца, остудить.','Тесто обмять и дать подняться ещё 40 минут.','Разделить на шарики, раскатать лепёшки, положить начинку и защипнуть. Выложить швом вниз на противень с бумагой и оставить на 15 минут.','Смазать яйцом, взбитым с ложкой воды, и печь около 15 минут при 180 °C.']::text[], 'https://www.gastronom.ru/recipe/41483/pirozhki-s-kapustoj-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
