insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-belyashi', 'Беляши', 'Пышное тесто, сочный фарш и дырочка сверху, через которую видно мясо', 'main', array['lunch','dinner','snack']::text[], 60, 165, 4, 2, 'red-meat', array['выходные']::text[], array['any']::text[], array['weekend']::text[], 'adapt', 'Для него 2–3 беляша из фарша без перца запечь в духовке 20–25 минут при 200 °C вместо жарки.', array['Замесить тесто из муки, 200 мл тёплого молока, дрожжей, сахара и соли. Оставить в тепле на 2 часа.','Лук прокрутить через мясорубку, смешать с фаршем, оставшимся молоком, солью и перцем.','Разделить тесто на булочки и дать им постоять 10–15 минут. Раскатать в лепёшки, смазывая стол и руки маслом вместо муки.','Положить фарш в центр и собрать края к середине, оставив сверху небольшую дырочку.','Жарить в сковороде с маслом слоем около 1 см, сначала дырочкой вниз, потом перевернуть, всего 8–10 минут до готовности фарша.']::text[], 'https://eda.rambler.ru/recepty/vypechka-deserty/belyashi-17047', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
