insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-shakshuka', 'Шакшука', 'Яйца в густом соусе из томатов и перца — хлебом собирать до дна', 'breakfast', array['breakfast','dinner']::text[], 15, 40, 4, 1, 'egg', array['будни']::text[], array['any']::text[], array['world']::text[], 'adapt', 'Его яйцо держать под крышкой ещё 3–4 минуты, до плотного желтка.', array['Лук и чеснок мелко нарезать, перец очистить от семян и нарезать кубиком.','Обжарить лук с чесноком на масле, добавить перец, затем паприку и томатную пасту.','Влить томаты, довести до кипения и томить на слабом огне 20–25 минут до густоты. Посолить.','Сделать в соусе углубления, вбить в них яйца и готовить под крышкой на слабом огне, пока не схватится белок.','Посыпать рубленой петрушкой и подавать с хлебом. Взрослым поперчить в тарелке.']::text[], 'https://www.gastronom.ru/recipe/44355/jaichnica-shakshuka-klassicheskij-recept', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
