insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-lagman', 'Лагман', 'Густая подлива с говядиной и овощами поверх длинной лапши', 'main', array['lunch','dinner']::text[], 35, 95, 4, 2, 'red-meat', array['на 2–3 дня']::text[], array['any']::text[], array['world']::text[], 'adapt', 'Мясо и лапшу ему нарезать мелко, перец только взрослым в тарелку.', array['Говядину нарезать кубиками и обжарить в казане на масле до румяной корочки, 10–12 минут.','Добавить нарезанные лук, морковь и перец, через пару минут — томатную пасту.','Влить 800 мл горячей воды, посолить, довести до кипения и тушить под крышкой 30 минут.','Добавить картофель кубиками, чеснок и зиру, тушить ещё 25–30 минут.','Лапшу отварить в подсоленной воде, откинуть и смазать каплей масла.','Разложить лапшу по тарелкам, залить подливой с мясом и посыпать зеленью. Взрослым поперчить в тарелке.']::text[], 'https://menunedeli.ru/recipe/lagman-s-govyadinoj-recept-klassicheskij-s-lapshoj/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
