insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-chakhokhbili', 'Чахохбили', 'Курица, томлённая с томатами, перцем и кинзой, — соус просит хлеба', 'main', array['lunch','dinner']::text[], 30, 55, 4, 2, 'poultry', '{}'::text[], array['any']::text[], array['world']::text[], 'adapt', 'Отложить его порцию до перца, курицу нарезать мелко.', array['Курицу нарезать средними кусками, лук и перец — тонкими полосками.','Обжарить курицу на масле до румяной корочки, добавить паприку, хмели-сунели и кориандр, прогреть минуту.','Добавить лук и перец и готовить около 5 минут, помешивая.','Выложить томаты с сахаром и тушить под крышкой около 15 минут. Посолить и поперчить.','Вмешать рубленые петрушку, кинзу и чеснок, снять с огня и оставить под крышкой на 15 минут.']::text[], 'https://www.iamcook.ru/showrecipe/29384', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
