insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-karri-slivochnoe', 'Курица с карри в молочном соусе', 'Нежная курица в мягком молочном соусе с карри, совсем без остроты', 'main', array['lunch','dinner']::text[], 25, 30, 4, 2, 'poultry', array['быстро','будни']::text[], array['any']::text[], array['world']::text[], 'adapt', 'Карри брать неострое, его порцию не перчить.', array['Подсушить муку на сухой сковороде на слабом огне 2–3 минуты, помешивая, и переложить в миску.','Курицу нарезать кубиками, посолить и обжарить на масле до румяной корочки.','Отдельно на небольшом огне обжарить мелко нарезанный лук до золотистого цвета.','Размешать муку в молоке до гладкости.','Добавить к курице лук, карри и молоко с мукой и тушить 2–3 минуты, помешивая, пока соус не загустеет.']::text[], 'https://eda.rambler.ru/recepty/osnovnye-blyuda/nezhnaja-kurica-v-slivochnom-souse-s-karri-41998', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
