insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-paelya', 'Паэлья с курицей', 'Золотистый рис с курицей, перцем и горошком — всё в одной сковороде', 'main', array['lunch','dinner']::text[], 30, 45, 4, 2, 'poultry', array['будни']::text[], array['any']::text[], array['world']::text[], 'adapt', 'Чёрный перец только взрослым в тарелку, курицу ему нарезать мельче.', array['Курицу нарезать кубиками, лук, морковь, перец и помидор — мелким кубиком.','На сильном огне обжарить курицу на масле около 5 минут, добавить лук и морковь и жарить ещё 5 минут.','Добавить болгарский перец и помидор, через 5 минут — горошек, чеснок, куркуму и соль. Прогреть 2–3 минуты.','Разровнять сверху промытый рис и залить горячей водой или бульоном так, чтобы жидкость покрывала его на 1–1,5 см.','Накрыть и томить на среднем огне 15–20 минут, пока рис не впитает жидкость. Посыпать петрушкой и дать постоять 5 минут.']::text[], 'https://1000.menu/cooking/44726-paelya-s-kuricei', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
