insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-lazanya', 'Лазанья', 'Слои пасты, мясного соуса и бешамеля под сырной корочкой', 'main', array['lunch','dinner']::text[], 40, 125, 6, 3, 'red-meat', array['выходные','духовка','на 2–3 дня']::text[], array['any']::text[], array['world']::text[], 'adapt', 'Мясной соус не перчить, взрослым поперчить в тарелке. Диме кусок нарезать мелко.', array['Лук и морковь мелко нарезать и обжарить на оливковом масле. Добавить фарш и жарить, разбивая комки.','Развести томатную пасту в 100 мл воды, влить к фаршу, посолить и тушить под крышкой около часа. За 30 минут до конца влить сливки.','Для бешамеля растопить сливочное масло, обжарить в нём муку минуту и понемногу влить горячее молоко, взбивая венчиком. Варить до загустения, посолить.','Собрать в форме слои: листы, мясной соус, бешамель, тёртый сыр. Повторять до конца продуктов, сверху — сыр.','Запекать около 30 минут при 180 °C, дать постоять 10 минут и нарезать.']::text[], 'https://www.edimdoma.ru/retsepty/23261-lazanya-samyy-prostoy-retsept', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
