insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-rizotto', 'Ризотто с курицей и горошком', 'Рис, который от помешивания становится кремом, с курицей и сыром', 'main', array['lunch','dinner']::text[], 35, 40, 4, 1, 'poultry', '{}'::text[], array['any']::text[], array['world']::text[], 'adapt', 'Его порцию не перчить, сыра положить поменьше: пармезан солёный.', array['Курицу обсушить, нарезать, посолить и обжарить на оливковом масле в глубокой сковороде около 10 минут. Переложить в миску.','Довести до кипения 600 мл бульона или воды и держать горячим на слабом огне.','В той же сковороде на сливочном масле потушить мелко нарезанный лук, всыпать рис и влить лимонный сок.','Вливать горячий бульон по половнику, помешивая и дожидаясь, пока впитается, 15–17 минут.','Влить сливки и дать им впитаться. Добавить горошек, курицу и тёртый сыр, прогреть 3 минуты и посыпать петрушкой.']::text[], 'https://www.gastronom.ru/recipe/55851/slivochnoe-rizotto-s-kuricej-i-zelenym-goroshkom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
