insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-ratatuy', 'Рататуй', 'Летние овощи, томлённые с травами, — к мясу, курице или просто с рисом', 'main', array['lunch','dinner']::text[], 25, 45, 4, 3, 'none', array['будни','постное','на 2–3 дня']::text[], array['summer','autumn']::text[], array['world']::text[], 'adapt', 'Отложить его порцию до перца, лавровый лист вынуть.', array['Лук нарезать полукольцами, чеснок — пластинками, перец — кусочками.','Баклажан и кабачок нарезать кубиками. Баклажан посолить на 15–20 минут, затем промыть и обсушить.','Помидоры нарезать кубиками того же размера.','В кастрюле с толстым дном обжарить лук с чесноком на масле. Добавить перец, баклажан, лавровый лист, соль и травы, накрыть и томить 10 минут, помешивая.','Добавить кабачок и тушить 5 минут, затем помидоры. Довести до кипения, посолить и поперчить.']::text[], 'https://www.edimdoma.ru/retsepty/29435-ratatuy-klassicheskiy-retsept', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
