insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-falafel-humus', 'Фалафель с хумусом', 'Нутовые шарики из духовки и нежный хумус — заворачивать в лаваш', 'main', array['lunch','dinner']::text[], 40, 840, 4, 3, 'legume', array['постное','духовка']::text[], array['any']::text[], array['world']::text[], 'adapt', 'Ему фалафель без перца, размять вилкой. Бобовые — не чаще 2–3 раз в неделю.', array['Нут промыть и замочить на ночь в холодной воде.','Воду слить, залить свежей и варить нут до мягкости около часа. Стакан отвара сохранить.','Для хумуса половину нута пробить блендером до гладкости, подливая отвар. Вмешать тахини, лимонный сок, чеснок, оливковое масло, зиру, паприку и соль. Убрать в холодильник на час.','Для фалафеля измельчить оставшийся нут с луком, петрушкой, чесноком, зирой, кориандром, солью и щепоткой перца.','Руками, присыпанными мукой, слепить шарики размером с грецкий орех.','Выложить на смазанный маслом противень и запекать 30 минут при 180 °C. Подавать с хумусом, завернув в лаваш.']::text[], 'https://www.edimdoma.ru/kulinarnaya_shkola/posts/21674-humus-i-falafel-kak-sdelat-doma-vostochnye-zakuski', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
