insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-kesadilya', 'Кесадилья с курицей и сыром', 'Хрустящая тортилья с курицей и тянущимся сыром, режется треугольниками', 'main', array['lunch','dinner','snack']::text[], 25, 30, 4, 1, 'poultry', array['быстро','будни','детское']::text[], array['any']::text[], array['world','quick-new']::text[], 'adapt', 'Начинку для него отложить до перца, кесадилью прогреть на сухой сковороде и нарезать полосками.', array['Лук и чеснок мелко нарезать, филе — тонкими ломтиками, помидор — кубиком.','Обжарить лук с чесноком на масле, добавить курицу и готовить около 8 минут.','Добавить помидор, через минуту посолить, приправить базиликом и перцем.','Натереть сыр. Собрать четыре кесадильи: на тортилью — сыр, начинку и снова сыр, накрыть второй тортильей и прижать.','Обжарить на сковороде с каплей масла: около 2 минут с одной стороны и минуту с другой. Разрезать и подавать со сметаной.']::text[], 'https://eda.rambler.ru/recepty/zakuski/domashnyaya-kesadilya-s-kuricey-i-syrom-124953', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
