insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-yaponskoe-karri', 'Японское карри с курицей', 'Густой мягкий соус с курицей, картошкой и морковью, а к нему — рис', 'main', array['lunch','dinner']::text[], 20, 45, 4, 2, 'poultry', array['будни']::text[], array['any']::text[], array['world']::text[], 'adapt', 'Карри брать неострое, перец только взрослым в тарелку, курицу и картошку ему размять.', array['С бёдер снять кожу, мясо срезать с костей и нарезать кусочками. Кости залить 700 мл воды и варить 10 минут — получится бульон.','Картофель и морковь нарезать небольшими кубиками, лук — полукольцами, обжарить на масле.','Карри, тёртый имбирь и соль размешать в половнике горячего бульона.','Добавить к овощам курицу, процеженный бульон со специями и, по желанию, мёд и тёртое яблоко. Довести до кипения.','Убавить огонь и тушить под крышкой около 20 минут, пока соус не загустеет.','Тем временем сварить рис: на 1 часть риса 2 части воды, 12–15 минут под крышкой, потом дать постоять.']::text[], 'https://www.iamcook.ru/showrecipe/6381', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
