insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-karbonara', 'Паста карбонара', 'Спагетти с беконом в соусе из желтков и сыра, и ни капли сливок', 'main', array['lunch','dinner']::text[], 20, 25, 4, 1, 'red-meat', array['быстро','будни']::text[], array['any']::text[], array['world']::text[], 'skip', 'Бекон и полусырые желтки ему нельзя: отложить спагетти до соуса и заправить сливочным маслом и тёртым сыром.', array['Отварить спагетти в подсоленной воде до аль денте, около 7 минут, и откинуть.','Желтки посолить, поперчить и смешать с половиной тёртого сыра.','Бекон нарезать полосками и обжарить на масле около 5 минут.','Выложить к бекону горячие спагетти, снять сковороду с огня, влить желтки с сыром и быстро перемешать.','Разложить по тарелкам и посыпать оставшимся сыром.']::text[], 'https://www.gastronom.ru/recipe/56539/pasta-karbonara', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
