insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-burgery', 'Бургеры домашние', 'Сочная говяжья котлета, сыр и овощи в поджаренной булке, как в бургерной', 'main', array['lunch','dinner']::text[], 25, 30, 4, 1, 'red-meat', array['быстро','будни','детское']::text[], array['any']::text[], array['cafe']::text[], 'adapt', 'Его котлету жарить под крышкой на слабом огне, пока срез не станет серым, без розового. Без горчицы и огурца; бургер разобрать и нарезать.', array['Сформовать из фарша 4 круглые котлеты чуть шире булочки и посолить.','Помидор нарезать кружками, огурцы — тонкими пластинами, салат промыть и обсушить.','Булочки разрезать и подсушить срезом на сухой сковороде.','Обжарить котлеты на сухой раскалённой сковороде до готовности, по 4–5 минут с каждой стороны, и сразу положить на каждую ломтик сыра.','Собрать: нижняя половинка с кетчупом, салат, помидор, огурец, котлета с сыром, смазанная горчицей, и верхняя половинка с кетчупом.']::text[], 'https://menunedeli.ru/recipe/burger-recept-v-domashnix-usloviyax/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
