insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-boul', 'Боул с курицей и рисом', 'Рис, курица и свежие овощи в одной миске — каждый собирает свою', 'main', array['lunch','dinner']::text[], 20, 40, 4, 1, 'poultry', array['будни']::text[], array['any']::text[], array['cafe']::text[], 'adapt', 'Его курицу не мариновать в соевом соусе, а потушить отдельно. Редис ему не давать.', array['Рис промыть, залить 700 мл воды и посолить. Варить под крышкой 5 минут на среднем огне и 10 минут на минимальном, потом дать постоять 10 минут.','Курицу нарезать небольшими кубиками и замариновать на 10–15 минут в соевом соусе с маслом и соком половины лимона.','Обжарить курицу с маринадом на сильном огне 5–8 минут, помешивая.','Нарезать огурцы, редис и помидоры.','Разложить по мискам рис и курицу, рядом овощи, добавить дольки лимона и посыпать кунжутом.']::text[], 'https://www.iamcook.ru/showrecipe/37688', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
