insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-shaurma', 'Шаурма домашняя', 'Курица, свежие овощи и чесночный соус в лаваше с хрустящей корочкой', 'main', array['lunch','dinner']::text[], 25, 30, 4, 1, 'poultry', array['быстро','будни']::text[], array['any']::text[], array['cafe']::text[], 'adapt', 'Его кусок филе потушить под крышкой с ложкой воды 10–12 минут, без перца. Завернуть в лаваш с огурцом и сметаной, без майонеза и чеснока, лаваш не обжаривать.', array['Филе нарезать пластинами, кусок для Димы отложить. Остальное обжарить на 4 ст. л. масла с двух сторон до готовности, посолить, поперчить, приправить паприкой и нарезать полосками.','Огурцы нарезать тонкими кружками, из помидоров удалить семена и нарезать ломтиками.','Для соуса смешать майонез, сметану и давленый чеснок, посолить.','Каждый лист лаваша разрезать пополам. Выложить курицу и овощи, полить соусом и свернуть плотным рулетом.','Обжарить шаурму на оставшемся масле с двух сторон до хрустящей корочки.']::text[], 'https://www.gastronom.ru/recipe/48879/shaurma-s-kuricej-v-domashnih-uslovijah', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
