insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-naggetsy', 'Наггетсы в духовке', 'Хрустящие кусочки курицы в сырной панировке, без капли фритюра', 'main', array['lunch','dinner','snack']::text[], 25, 45, 4, 2, 'poultry', array['будни','духовка','детское']::text[], array['any']::text[], array['cafe','kids-cook']::text[], 'adapt', 'Его кусочки обвалять в муке без перца, давать нарезанными.', array['Разогреть духовку до 210 °C. Противень застелить бумагой и смазать маслом.','Приготовить три миски: мука с травами, солью и перцем; желтки, взбитые с 3 ст. л. воды; сухари с тёртым сыром.','Филе обсушить и нарезать кусочками поперёк волокон.','Каждый кусочек обвалять в муке, окунуть в желтки, затем в сырные сухари и выложить на противень.','Сбрызнуть маслом и запекать 10 минут, перевернуть и запекать ещё 10–15 минут до румяной корочки.']::text[], 'https://www.gastronom.ru/recipe/51346/kurinye-naggetsy-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
