insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-kartofel-po-derevenski', 'Картофель по-деревенски с соусом', 'Румяные дольки с паприкой и холодный соус с огурцом и укропом', 'snack', array['lunch','dinner','snack']::text[], 15, 50, 4, 1, 'none', array['духовка','бюджетное','детское']::text[], array['any']::text[], array['cafe']::text[], 'adapt', 'Ему дольки без соуса или с ложкой сметаны, сильно подрумяненную корочку срезать.', array['Картофель очистить и нарезать вдоль дольками.','Варить в подсоленной воде 5 минут после закипания, слить воду и дать стечь.','Растопить масло, смешать с паприкой, полить картофель и встряхнуть, чтобы масло распределилось.','Выложить в один слой на противень с бумагой и запекать при 250 °C около 30 минут, пару раз перемешав. Проверять с 17-й минуты.','Для соуса смешать сметану, майонез, тёртый огурец, давленый чеснок и рубленый укроп, посолить и поперчить.']::text[], 'https://www.edimdoma.ru/retsepty/142127-kartofel-po-derevenski', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
