insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-klab-sendvich', 'Клаб-сэндвич', 'Трёхэтажный тост с курицей, беконом, сыром и овощами, разрезанный наискосок', 'main', array['lunch','dinner','snack']::text[], 25, 30, 4, 1, 'poultry', array['быстро','будни']::text[], array['any']::text[], array['cafe']::text[], 'adapt', 'Ему тост с курицей, помидором и сыром, без бекона, майонеза и горчицы.', array['Майонез смешать с горчицей. Курицу посолить и поперчить с двух сторон.','Хлеб подсушить в тостере или на сухой сковороде.','Курицу обжарить на сковороде-гриль по 2 минуты с каждой стороны и довести в духовке при 180 °C около 8 минут. Нарезать ломтиками.','Тост смазать соусом, положить салат, курицу и сыр, накрыть вторым тостом, тоже смазанным соусом.','Сверху выложить салат, помидор, сыр и бекон, накрыть третьим тостом и разрезать наискосок.']::text[], 'https://www.edimdoma.ru/retsepty/132002-klubnyy-sendvich-s-kuritsey-i-bekonom', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
