insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-lapsha-vok', 'Лапша вок с курицей и овощами', 'Яичная лапша, курица и кабачок в соевом соусе — быстрее доставки', 'main', array['lunch','dinner']::text[], 20, 40, 4, 1, 'poultry', array['будни']::text[], array['any']::text[], array['quick-new']::text[], 'adapt', 'Отложить ему кусочек курицы без соевого соуса и потушить отдельно, лапшу с овощами нарезать коротко.', array['Курицу нарезать полосками, залить соевым соусом и оставить на 20 минут.','Кабачок нарезать полукольцами, морковь — тонкими лентами овощечисткой, лук — полукольцами.','Обжарить курицу на сильном огне в воке или сковороде, добавить лук и остальные овощи и жарить, помешивая.','Лапшу отварить 2–3 минуты, до полуготовности, и откинуть.','Переложить лапшу к курице с овощами и обжарить вместе пару минут. Подавать со свежим огурцом и кунжутом.']::text[], 'https://1000.menu/cooking/17357-yaichnaya-lapsha-s-kuricei-i-ovoshchami', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
