insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-zharenyy-ris', 'Жареный рис с яйцом и овощами', 'Рассыпчатый рис с кусочками омлета, перцем и горошком, как в китайском кафе', 'main', array['lunch','dinner']::text[], 25, 55, 4, 1, 'egg', '{}'::text[], array['any']::text[], array['quick-new']::text[], 'adapt', 'Ему взбить пару яиц без соевого соуса и перца, приготовить омлет под крышкой и смешать с рисом и горошком.', array['Рис обжарить на ложке масла, влить лимонный сок и 400 мл горячей воды. Варить под крышкой на минимальном огне 12–14 минут.','Горошек залить кипятком на 5 минут. Перец и помидор нарезать мелким кубиком, зелёный лук и чеснок измельчить.','Яйца взбить с соевым соусом, солью и перцем, добавить овощи.','Вылить яичную смесь на разогретое масло и готовить на слабом огне 3 минуты, затем разбить лопаткой на кусочки и жарить ещё 2 минуты.','Добавить рис, перемешать, накрыть на минуту и подавать.']::text[], 'https://www.gastronom.ru/recipe/58469/zharenyj-ris-po-kitajski', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
