insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-pasta-tunec', 'Паста с тунцом и томатами', 'Спагетти с тунцом, томатами и оливками из того, что лежит в шкафу', 'main', array['lunch','dinner']::text[], 20, 30, 4, 1, 'fish', array['быстро','будни']::text[], array['any']::text[], array['quick-new']::text[], 'adapt', 'Его порцию отложить до оливок и перца, тунец размять.', array['Отварить спагетти по инструкции, оставив 100 мл воды от варки.','Лук и чеснок измельчить, оливки нарезать кружками, петрушку порубить.','Обжарить лук с чесноком на масле до прозрачности, добавить цедру и томаты и тушить 5 минут на слабом огне.','Слить жидкость с тунца, добавить рыбу и пасту, подлить немного воды от варки, посолить и прогреть минуту. Отложить Диме порцию, в остальное добавить оливки и поперчить.','Разложить по тарелкам и посыпать петрушкой.']::text[], 'https://www.gastronom.ru/recipe/61295/pasta-s-tomatami-i-tuncom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
