insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-krok-mesye', 'Крок-месье', 'Горячий французский бутерброд с ветчиной, сыром и шапкой бешамеля', 'breakfast', array['breakfast','lunch','snack']::text[], 25, 30, 4, 1, 'dairy', array['быстро','будни']::text[], array['any']::text[], array['quick-new']::text[], 'adapt', 'Ему бутерброд без ветчины, с сыром и бешамелем, прогреть в духовке, а не жарить.', array['Для бешамеля растопить 40 г масла, обжарить в нём муку около минуты и тонкой струйкой влить горячее молоко, помешивая. Варить до загустения и посолить.','Хлеб смазать маслом с одной стороны. На половину ломтиков, маслом вниз, положить сыр и ветчину и накрыть остальными, маслом наружу.','Обжаривать на сковороде-гриль на среднем огне 7 минут с одной стороны и 4 минуты с другой.','Покрыть бутерброды бешамелем и запечь под грилем в духовке 1–2 минуты.']::text[], 'https://www.gastronom.ru/recipe/59520/krok-mese-s-sousom-beshamel', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
