insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-tortilya', 'Испанская тортилья', 'Толстый омлет с мягкой картошкой и луком, вкусный и горячим, и холодным', 'breakfast', array['breakfast','lunch','dinner']::text[], 30, 35, 4, 1, 'egg', array['будни']::text[], array['any']::text[], array['quick-new']::text[], 'adapt', 'Его часть смеси без перца запечь в маленькой форме 20 минут при 180 °C вместо жарки.', array['Картофель нарезать тонкими кружками и жарить на масле на слабом огне около 15 минут, не допуская корочки. На полпути добавить мелко нарезанный лук.','Яйца взбить с солью, переложить к ним картофель с луком без лишнего масла и слегка размять вилкой. Отложить Диме его часть, остальное поперчить.','Вылить смесь в сковороду с маслом и готовить 3 минуты на среднем огне, затем на слабом, пока верх почти не схватится.','Сдвинуть тортилью на тарелку, накрыть сковородой и перевернуть обратно.','Готовить вторую сторону около 3 минут и проверить зубочисткой.']::text[], 'https://eda.rambler.ru/recepty/zavtraki/ispanskaja-tortilja-s-kartofelem-i-lukom-38842', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
