insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-chizkeyk', 'Чизкейк без выпечки', 'Нежный крем из творожного сыра на хрустящей основе из печенья, без духовки', 'dessert', array['snack']::text[], 35, 150, 8, 3, 'dairy', array['праздничное']::text[], array['any']::text[], array['sweet']::text[], 'adapt', 'Маленький кусочек. Сладкое — не чаще 2–3 раз в неделю.', array['Печенье измельчить в крошку и смешать с растопленным маслом.','Дно формы 22 см застелить плёнкой, утрамбовать крошку и убрать в холодильник.','Желатин залить 100 мл холодной воды и оставить набухать.','Сыр взбить с сахарной пудрой и ванильным сахаром, влить сливки и взбивать ещё минуту.','Желатин растопить на очень слабом огне, не кипятя, и быстро вмешать частями в сырную массу.','Вылить крем на основу, разровнять и убрать в холодильник на 1,5–2 часа.']::text[], 'https://menunedeli.ru/recipe/chizkejk-recept-bez-vypechki-s-pechenem/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
