insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-panna-kotta', 'Панна-котта с ягодным соусом', 'Сливочное желе с ванилью под тёплым ягодным соусом', 'dessert', array['snack']::text[], 30, 390, 6, 3, 'dairy', array['праздничное']::text[], array['any']::text[], array['sweet']::text[], 'adapt', 'Половинка порции. Сладкое — не чаще 2–3 раз в неделю.', array['Желатин замочить в небольшом количестве воды, как написано на упаковке.','Сливки прогреть со 100 г сахара и ванильным сахаром на умеренном огне до растворения сахара, не доводя до кипения.','Добавить желатин, размешать до полного растворения и разлить по 6 формочкам, примерно по 80 мл.','Остудить при комнатной температуре и убрать в холодильник на 6 часов.','Для соуса прогреть ягоды с 50 г сахара и цедрой на раскалённой сковороде, пока не пустят сок, и остудить.','Выложить панна-котту на тарелки и полить соусом.']::text[], 'https://www.gastronom.ru/recipe/57342/vanilnaja-panakota-s-jagodnym-sousom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
