insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-blinnyy-tort', 'Блинный торт со сметанным кремом', 'Два десятка тонких блинов, переложенных сметанным кремом', 'dessert', array['snack']::text[], 70, 270, 10, 2, 'dairy', array['праздничное','выходные']::text[], array['any']::text[], array['sweet']::text[], 'adapt', 'Маленький кусочек. Сладкое — не чаще 2–3 раз в неделю.', array['Яйца взбить с солью и 2 ложками сахара, влить молоко комнатной температуры.','Понемногу вмешать просеянную муку до консистенции жидкой сметаны, добавить соду и масло. Дать тесту постоять 15–20 минут.','Жарить тонкие блины на хорошо разогретой сковороде, смазав её маслом только перед первым. Сложить стопкой и остудить.','Охлаждённую сметану взбить с сахаром и ванильным сахаром до густоты.','Собрать торт, смазывая каждый блин тонким слоем крема. Украсить ягодами.','Убрать в холодильник на 3 часа, чтобы торт пропитался.']::text[], 'https://www.edimdoma.ru/retsepty/124820-blinnyy-tort-so-smetannym-kremom', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
