insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-muraveynik', 'Торт «Муравейник»', 'Горка из хрустящего печенья со сливочно-карамельным кремом', 'dessert', array['snack']::text[], 50, 240, 10, 4, 'none', array['праздничное','духовка','выходные']::text[], array['any']::text[], array['sweet']::text[], 'adapt', 'Маленький кусочек без шоколадной посыпки. Сладкое — не чаще 2–3 раз в неделю.', array['200 г масла растопить и остудить. Масло для крема заранее достать, чтобы размягчилось.','Смешать сметану с растопленным маслом, добавить сахар и ванильный сахар и взбить.','Муку просеять с разрыхлителем, постепенно вмешать и вымесить тесто.','Прокрутить тесто через мясорубку прямо на противень с бумагой, разбирая «лапшу».','Печь 15–20 минут при 180 °C до золотистого цвета, остудить и раскрошить.','Мягкое масло взбить со сгущёнкой, смешать с крошкой, выложить горкой и убрать в холодильник минимум на 2 часа. Перед подачей посыпать тёртым шоколадом.']::text[], 'https://www.gastronom.ru/recipe/6795/tort-muravejnik', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
