insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-brauni', 'Брауни', 'Шоколадный квадратик с влажной серединкой и тонкой корочкой сверху', 'dessert', array['snack']::text[], 15, 60, 8, 4, 'none', array['духовка']::text[], array['any']::text[], array['sweet']::text[], 'skip', 'Шоколад малышу не дают. Ему — печенье-фигурку или банан.', array['Растопить шоколад с маслом на водяной бане, следя, чтобы в миску не попала вода.','Всыпать сахар и дать ему раствориться. Снять с огня и немного остудить.','Вбивать яйца по одному, каждый раз хорошо перемешивая.','Вмешать просеянную муку до однородности.','Выложить тесто в форму 13×19 см с бумагой и печь 30–35 минут при 170 °C. Середина должна остаться чуть влажной.','Остудить в форме, нарезать квадратами и при желании посыпать какао.']::text[], 'https://menunedeli.ru/recipe/recept-brauni-klassicheskij/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
