insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-morkovnyy-tort', 'Морковный торт', 'Влажный пряный корж с морковью и орехами под шапкой сливочного крема', 'dessert', array['snack']::text[], 30, 125, 6, 4, 'none', array['духовка','праздничное']::text[], array['any']::text[], array['sweet']::text[], 'adapt', 'Маленький кусочек, перец в тесто не класть, орехи истолочь мелко.', array['Морковь натереть на мелкой тёрке, смешать с солью, корицей и толчёными орехами.','Яйца взбить с сахаром и маслом до светлой однородной массы.','Добавить морковь, затем просеянную муку с разрыхлителем и перемешать.','Выложить в форму и печь 20 минут при 180 °C, потом ещё 20 минут при 160 °C. Корж полностью остудить.','Творожный сыр взбить с сахарной пудрой до гладкости и намазать на корж.']::text[], 'https://eda.rambler.ru/recepty/vypechka-deserty/prostoy-morkovnyy-tort-so-slivochnym-kremom-138685', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
