insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-pizza-lavash', 'Пицца на лаваше', 'Лаваш вместо теста: дети сами мажут соус и раскладывают начинку', 'snack', array['snack','dinner']::text[], 15, 20, 4, 1, 'dairy', array['быстро','духовка','детское']::text[], array['any']::text[], array['kids-cook']::text[], 'ok', 'Нарезать кусочками помельче.', array['Разогреть духовку до 250 °C. Помидоры и перец нарезать тонкими ломтиками, сыр натереть.','Каждый лаваш смазать томатной пастой — это можно доверить детям.','Разложить помидоры и перец и посыпать сыром.','Запекать 4–5 минут, пока сыр не расплавится.']::text[], 'https://www.gastronom.ru/recipe/56485/picca-za-5-minut', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
