insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-pechenye-figurki', 'Печенье-фигурки', 'Звёздочки и зверушки из песочного теста, вырезанные формочками', 'dessert', array['snack']::text[], 35, 55, 10, 7, 'none', array['духовка','детское']::text[], array['any']::text[], array['kids-cook']::text[], 'adapt', 'Одна-две фигурки. Сладкое — не чаще 2–3 раз в неделю.', array['Растопить масло, добавить сахар и взбить.','Вмешать яйца, ванильный сахар и корицу.','Постепенно добавить муку с разрыхлителем и замесить плотное тесто.','Разделить тесто на две части и раскатать каждую пластом 0,5–1 см.','Вырезать фигурки формочками и выложить на бумагу для выпечки.','Печь около 15 минут при 150 °C до светло-пшеничного цвета.']::text[], 'https://www.edimdoma.ru/retsepty/77094-prostoe-pesochnoe-pechenie', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
