insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('ex-pankeyki', 'Панкейки', 'Пышные американские блинчики стопкой — с мёдом, ягодами или сгущёнкой', 'breakfast', array['breakfast','snack']::text[], 30, 45, 4, 1, 'none', array['будни','детское']::text[], array['any']::text[], array['kids-cook']::text[], 'ok', 'Подавать с ягодами или бананом.', array['Заранее достать молоко и яйцо, чтобы они согрелись до комнатной температуры.','Взбить яйцо с молоком, сахаром, ванильным сахаром, маслом и солью.','Муку просеять с разрыхлителем и понемногу вмешать в жидкую часть без комков. Дать тесту постоять 10–15 минут.','Разогреть сухую сковороду на среднем огне и выкладывать тесто ложкой. Когда на поверхности появятся дырочки, перевернуть и жарить ещё около 2 минут.','Подавать горячими с мёдом, ягодами или сгущёнкой.']::text[], 'https://menunedeli.ru/recipe/pankejki-recept-klassicheskij/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
