insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-molodaya-kapusta-s-ogurcom', 'Салат из молодой капусты с огурцом и укропом', 'Молодая капуста с огурцом и укропом под маслом, без уксуса', 'salad', array['lunch','dinner']::text[], 10, 30, 4, 1, 'none', array['быстро','без плиты','постное','бюджетное']::text[], array['spring','summer']::text[], '{}'::text[], 'adapt', 'Отложить ему капусту с огурцом до чеснока и перца, нашинковать мельче, посыпать просто рубленым укропом и заправить маслом.', array['Капусту тонко нашинковать, посолить, помять руками и оставить на 15 минут.','Пока капуста стоит, нарезать огурцы тонкой соломкой.','Укроп мелко порубить без толстых стеблей, добавить давленый чеснок и щепотку соли, помять и оставить на 10 минут.','Капусту слегка отжать от сока, смешать с огурцами и укропом, поперчить и заправить маслом.']::text[], 'https://www.gastronom.ru/recipe/58429/salat-iz-svezhej-kapusty-s-ogurcom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
