insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-kurinyi-so-shpinatom', 'Куриный суп со шпинатом и яйцом', 'Весенний суп на курином бульоне со шпинатом и яичными хлопьями', 'soup', array['lunch']::text[], 25, 70, 10, 3, 'poultry', array['на 2–3 дня']::text[], array['spring','summer']::text[], '{}'::text[], 'adapt', 'Отлить его порцию, когда влили яйцо и вернули курицу, — до зажарки, соли и перца. Курицу нарезать мельче.', array['Филе залить 4 л холодной воды, довести до кипения, снять пену, положить лавровый лист и варить на слабом огне 30 минут.','Филе вынуть, остудить и нарезать кубиками. Бульон процедить и вернуть на огонь.','Картофель нарезать кубиками, опустить в кипящий бульон и варить 10 минут. Тем временем крупно нарезать лук и морковь и обжарить на масле 5–7 минут.','Шпинат промыть, срезать жёсткие черешки, листья нарезать полосками, положить в суп и варить 5 минут.','Яйца взбить вилкой и тонкой струйкой влить в суп, всё время помешивая. Вернуть в суп курицу.','Добавить зажарку, посолить, поперчить, прогреть пару минут и оставить под крышкой на 10 минут. Подавать с рубленым укропом и сметаной.']::text[], 'https://www.gastronom.ru/recipe/65022/kurinyj-sup-so-shpinatom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
