insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-molodaya-kartoshka-s-tuncom', 'Молодая картошка с тунцом и петрушкой', 'Молодая картошка с петрушкой и лимоном и соус из тунца с йогуртом', 'main', array['lunch','dinner']::text[], 15, 40, 4, 1, 'fish', array['будни']::text[], array['spring','summer']::text[], '{}'::text[], 'adapt', 'Майонез и солёные огурцы нельзя. Отложить ему пару ложек тунца до соуса, проверить на кости и размять с йогуртом. Картошку взять отварную до обжарки, без перца, размять.', array['Картофель отмыть щёткой и сварить в кожуре до мягкости, около 20 минут.','Пока варится картофель, размять тунец вилкой и смешать с йогуртом, майонезом, 3–4 ст. л. лимонного сока и мелко нарубленными огурцами. Посолить и поперчить.','Петрушку мелко порубить, с лимона снять цедру.','Слить воду с картофеля. В широкой сковороде разогреть оливковое и сливочное масло и слегка обжарить картофель 3–4 минуты, встряхивая сковороду.','Добавить цедру и петрушку, посолить, поперчить и сразу подавать с соусом из тунца.']::text[], 'https://www.gastronom.ru/recipe/42088/molodoj-kartofel-s-petrushkoj-i-tuncom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
