insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-okroshka-na-kvase', 'Окрошка на квасе с говядиной', 'Классическая окрошка с говядиной; основу и квас хранить отдельно', 'soup', array['lunch','dinner']::text[], 45, 200, 10, 2, 'red-meat', array['на 2–3 дня','выходные']::text[], array['spring','summer']::text[], '{}'::text[], 'adapt', 'Квас, редис и горчицу малышу нельзя. Отложить ему основу до редиса, нарезать мельче и залить кефиром без соли и перца.', array['Говядину целым куском залить водой, довести до кипения, снять пену и варить на слабом огне около 1,5 часа до мягкости. Остудить.','Пока варится мясо, сварить картофель в мундире 20–25 минут, яйца — вкрутую 8 минут. Остудить и очистить.','Картофель, яйца и огурцы нарезать кубиками, редис — тонкими кружками, говядину — тонкой соломкой. Перемешать — это основа.','Основу и квас убрать в холодильник хотя бы на час. Хранить отдельно, не дольше двух дней.','Перед подачей разложить основу по тарелкам, посолить, поперчить, залить холодным квасом и посыпать рубленой зеленью. Сметану и горчицу подать отдельно.']::text[], 'https://www.gastronom.ru/recipe/57026/okroshka-s-govjadinoj', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
