insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-gaspacho', 'Гаспачо по-домашнему', 'Холодный суп из спелых помидоров, огурца и перца — без варки', 'soup', array['lunch','dinner']::text[], 40, 100, 10, 2, 'none', array['на 2–3 дня','без плиты','постное']::text[], array['summer']::text[], '{}'::text[], 'adapt', 'Лук, чеснок, уксус, чили и перец малышу нельзя. До блендера отложить ему помидор, кусочек огурца, перца и хлеба и пробить отдельно с ложкой масла.', array['Хлеб нарезать кубиками, лук мелко порубить. Смешать с уксусом, накрыть и убрать в холодильник, пока готовятся овощи.','Помидоры надрезать крестом, залить кипятком из чайника на минуту, затем холодной водой. Снять кожицу, вырезать плодоножки.','Огурцы очистить, у перца удалить семена и плодоножку. Все овощи крупно нарезать, чеснок очистить.','Партиями пробить блендером помидоры, огурцы, перец, чеснок, базилик и чили вместе с хлебом и луком, влить масло. Посолить, поперчить, по вкусу добавить ещё каплю уксуса.','Убрать в холодильник минимум на час. Перед подачей перемешать, слишком густой суп разбавить холодной водой.']::text[], 'https://menunedeli.ru/recipe/gaspacho-recept-klassicheskij/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
