insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-govyadina-s-chernoslivom', 'Говядина, тушённая с черносливом', 'Мягкая говядина с луком и черносливом в густой подливке', 'main', array['lunch','dinner']::text[], 20, 80, 4, 2, 'red-meat', array['выходные','на 2–3 дня']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Отложить его порцию до соли и перца, мясо нарезать мелко, чернослив размять.', array['Лук нарезать полукольцами и обжарить на масле в толстостенной кастрюле 5 минут.','Говядину нарезать пластинами толщиной 1 см и выложить поверх лука.','Когда мясо пустит сок, добавить промытый чернослив и лавровый лист, перемешать.','Тушить под крышкой на слабом огне 50 минут. Если сок выкипает, подлить немного горячей воды.','Всыпать муку, хорошо перемешать и тушить ещё 10 минут, пока подливка не загустеет. Посолить и поперчить в конце.']::text[], 'https://eda.rambler.ru/recepty/osnovnye-blyuda/govjadina-tushenaja-s-chernoslivom-46646', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
