insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-svinina-so-svekloy-i-morkovyu', 'Свинина, запечённая со свёклой и морковью', 'Свинина в духовке на подушке из свёклы, моркови и лука', 'main', array['lunch','dinner']::text[], 15, 115, 4, 2, 'red-meat', array['духовка']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Его кусок натереть только солью и паприкой, без чёрного перца. Мясо и морковь нарезать мелко, свёклу размять.', array['Свинину нарезать порционными кусками, с двух сторон натереть солью, паприкой и перцем, накрыть и убрать в холодильник на час.','Свёклу разрезать пополам и нарезать тонкими полукружьями, морковь — тонкими кружками, лук — кольцами.','Форму смазать маслом, выложить овощи ровным слоем и слегка посолить.','Сверху разложить мясо и запекать при 180 °C около 35 минут, пока сок при проколе не станет прозрачным. Для румяной корочки последние 5–10 минут можно запекать при 200–220 °C.','Подавать с овощами из-под мяса, посыпав петрушкой.']::text[], 'https://www.edimdoma.ru/retsepty/129174-myaso-zapechennoe-so-svekloy-morkovyu-i-lukom', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
