insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-zapekanka-tykva-indeyka', 'Запеканка из тыквы с фаршем индейки', 'Слои тыквы и фарша индейки под сырной корочкой', 'main', array['lunch','dinner']::text[], 25, 80, 4, 2, 'poultry', array['духовка','на 2–3 дня']::text[], array['autumn','winter']::text[], '{}'::text[], 'ok', 'Сыр взять неострый, порцию нарезать мелко.', array['Тыкву очистить от кожуры и семян и нарезать мелкими кубиками.','Лук мелко нарезать, чеснок натереть. Смешать с фаршем, паприкой и солью.','Обжарить фарш на масле на слабом огне 5–7 минут, разбивая комочки. Немного остудить.','Форму смазать сливочным маслом. Выложить половину тыквы и слегка посолить, сверху фарш, затем оставшуюся тыкву и снова чуть посолить.','Сверху разложить кусочки сливочного масла, накрыть фольгой и запекать при 180 °C 40–45 минут.','Снять фольгу, посыпать тёртым сыром и запекать ещё 5–7 минут, пока сыр не расплавится.']::text[], 'https://www.gastronom.ru/recipe/44810/zapekanka-iz-tykvy-s-farshem-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
