insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-shashlyk-kurica-kefir', 'Шашлык из курицы в кефире', 'Куриное филе в кефире с кориандром и зирой — на мангале или в духовке', 'main', array['lunch','dinner']::text[], 35, 100, 4, 2, 'poultry', array['выходные']::text[], array['spring','summer']::text[], '{}'::text[], 'adapt', 'Отложить ему 150 г филе в кефир без соли и специй и запечь в фольге в духовке 20–25 минут. Без поджаристой корочки, нарезать мелко.', array['Филе нарезать кубиками около 3 см.','Растереть 1 ч. л. соли, 1 ст. л. молотого кориандра, 1 ч. л. зиры и 1 ч. л. куркумы. Размешать специи в кефире, добавить курицу и перемешать руками.','Мариновать в холодильнике от 1 до 5–6 часов, не дольше: мясо станет рыхлым.','Растопить сливочное масло и смешать с соком половины лимона.','Плотно нанизать курицу на шампуры.','На мангале — жарить на углях 15–20 минут, часто переворачивая и смазывая лимонным маслом.','В духовке — на решётке над противнем при 220 °C 20–25 минут, через 10 минут перевернуть и смазать маслом.','Снимать, когда сок при проколе прозрачный.']::text[], 'https://eda.rambler.ru/recepty/osnovnye-blyuda/shashlik-iz-kurici-28051', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
