insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-shashlyk-svinina', 'Шашлык из свинины с луком', 'Свиная шейка в луковом маринаде с зирой и кориандром, без уксуса', 'main', array['lunch','dinner']::text[], 40, 180, 4, 2, 'red-meat', array['выходные']::text[], array['spring','summer']::text[], '{}'::text[], 'adapt', 'Отложить ему 150 г мяса в лук со щепоткой соли, без перца и зиры, и запечь в фольге в духовке 30 минут до мягкости. Без корочки, нарезать мелко.', array['2 ч. л. зиры и 2/3 ч. л. кориандра прогреть на сухой сковороде 1,5–2 минуты, остудить и растереть с 2 ч. л. соли. Добавить чёрный перец.','Лук тонко нарезать кольцами. Свинину нарезать кусками примерно 5×3×3 см и натереть смесью специй.','Соединить мясо с луком и хорошо помять руками, чтобы лук пустил сок. Накрыть и мариновать 2 часа при комнатной температуре или до 12 часов в холодильнике.','Мясо освободить от лука и нанизать на шампуры.','На мангале — жарить на углях 15–20 минут до прозрачного сока, часто переворачивая.','В духовке — на решётке над противнем при 220 °C 25–30 минут, перевернуть через 15 минут.','Пока жарится мясо, обжарить лук из маринада на масле до золотистого цвета и подать к шашлыку.']::text[], 'https://www.gastronom.ru/recipe/47015/klassicheskij-shashlyk-iz-svininy-s-lukom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
