insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-svinina-so-struchkovoy-fasolyu', 'Свинина со стручковой фасолью', 'Свинина с зелёной фасолью в томатном соусе за полчаса', 'main', array['lunch','dinner']::text[], 25, 30, 4, 2, 'red-meat', array['быстро','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить его порцию до соли и перца, мясо нарезать мелко. Если кусочки жестковаты, потушить его порцию в соусе под крышкой ещё 10 минут.', array['Свинину нарезать брусочками, лук — тонкими полукольцами, чеснок мелко порубить. Фасоль размораживать не нужно.','Разогреть масло и обжарить лук с чесноком пару минут, до прозрачности.','Добавить свинину и жарить 5–7 минут, помешивая, до лёгкой корочки.','Положить фасоль, жарить ещё минуту и посыпать паприкой и травами.','Всыпать муку и перемешать, чтобы не осталось белых комочков. Развести томатную пасту в 200–250 мл воды, влить и прогреть 1–2 минуты до загустения. Посолить и поперчить.','Кто любит острое, добавляет мелко нарезанный чили в свою тарелку.']::text[], 'https://www.iamcook.ru/showrecipe/36118', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
