insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-farsh-s-fasolyu-i-kukuruzoy', 'Говяжий фарш с фасолью и кукурузой', 'Фарш с фасолью, кукурузой и перцем по-мексикански, острота — по вкусу', 'main', array['lunch','dinner']::text[], 25, 40, 4, 2, 'red-meat', array['будни','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить его порцию до соли, перца и чили. Фасоль и кукурузу размять вилкой.', array['Фасоль и кукурузу откинуть на дуршлаг. Лук, чеснок и помидоры нарезать кубиком, перец — соломкой.','Разогреть масло, выложить фарш и жарить на сильном огне 5–7 минут, разбивая комочки вилкой.','Добавить лук, чеснок и перец и жарить 4–5 минут, помешивая.','Положить помидоры, убавить огонь до среднего и тушить 10 минут. Если суховато, подлить до 100 мл кипятка.','Когда овощи станут мягкими, добавить фасоль и кукурузу и прогреть 5–7 минут, помешивая. Посолить и поперчить.','Добавить чили по вкусу и рубленую зелень. Подавать с рисом или завернуть в лепёшки.']::text[], 'https://www.iamcook.ru/showrecipe/24221', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
