insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-hek-s-pomidorami-i-syrom', 'Хек, запечённый с помидорами и сыром', 'Филе хека слоями с помидорами под сырной корочкой, без жарки', 'main', array['lunch','dinner']::text[], 15, 45, 4, 2, 'fish', array['будни','духовка']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек проверить на кости, перец только взрослым в тарелку.', array['Включить духовку на 180 °C. Филе нарезать порционными кусками, посолить и посыпать орегано.','Помидоры нарезать кружками, сыр натереть на крупной тёрке.','Смазать форму маслом и выложить половину рыбы в один слой. Смазать половиной сметаны, сверху разложить половину помидоров и посыпать половиной сыра.','Повторить слои из оставшейся рыбы, сметаны, помидоров и сыра.','Накрыть форму фольгой и запекать 20 минут, затем снять фольгу и запекать ещё 10 минут, пока сыр не подрумянится.']::text[], 'https://1000.menu/cooking/43362-file-xeka-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
