insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-treska-na-paru-s-ovoshchami', 'Треска на пару с овощами', 'Рыба и овощи готовятся вместе на пару за 15 минут, без жарки', 'main', array['lunch','dinner']::text[], 10, 30, 4, 1, 'fish', array['быстро','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек проверить на кости, фасоль порезать мельче, перец только взрослым.', array['Филе очистить от кожи и костей, нарезать порциями, посолить и посыпать сушёным базиликом.','Кабачок нарезать шайбами толщиной около 1 см и выложить в корзину пароварки или мультиварки, слегка посолить.','Сверху разложить стручковую фасоль, на неё — рыбу.','Закрыть крышкой и готовить на пару 15 минут.','Растопить сливочное масло. Разложить овощи по тарелкам, сверху рыбу, полить маслом и лимонным соком, посыпать петрушкой.']::text[], 'https://menunedeli.ru/recipe/treska-s-ovoshhami-na-paru/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
