insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-gorbusha-v-slivkah', 'Горбуша в сливках на сковороде', 'Нежная горбуша в сливках с луком — ужин за 25 минут', 'main', array['lunch','dinner']::text[], 20, 25, 4, 1, 'fish', array['быстро','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек без муки и жарки: положить сырым в сливки вместе со всеми и потушить под крышкой 8–10 минут. Кожу и кости убрать, не перчить.', array['Филе обсушить, нарезать кусками, посолить.','Лук нарезать и обжарить на масле до мягкости, около 5 минут. Переложить в тарелку.','Рыбу обвалять в муке и на той же сковороде обжарить по 2 минуты с каждой стороны.','Вернуть лук, влить сливки и держать на слабом огне 3 минуты.','Накрыть крышкой, снять с огня и дать постоять 5 минут.']::text[], 'https://www.iamcook.ru/showrecipe/20204', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
