insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-mintay-s-risom-i-ovoshchami', 'Минтай с рисом и овощами на сковороде', 'Рыба, рис и овощи в одной сковороде — гарнир отдельно не нужен', 'main', array['lunch','dinner']::text[], 20, 45, 4, 2, 'fish', array['будни','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Лавровый лист вынуть, рыбу проверить на кости, перец только взрослым в тарелку.', array['Рис промыть до прозрачной воды и дать стечь. Филе нарезать кусками, посолить, посыпать базиликом и оставить на 15 минут.','Лук мелко нарезать, морковь натереть, перец нарезать брусочками.','На масле обжарить лук 2–3 минуты, добавить морковь ещё на 2–3 минуты, затем перец на 2 минуты.','Подлить немного масла, всыпать рис и прогревать 2 минуты, помешивая.','Сметану развести 350 мл горячей воды и посолить. Разложить рыбу поверх риса, залить соусом, добавить лавровый лист.','Накрыть крышкой и тушить на слабом огне 20–25 минут, пока рис не станет мягким. Дать постоять 5 минут и посыпать зеленью.']::text[], 'https://www.gastronom.ru/recipe/64642/mintaj-s-risom-i-ovoshami-na-skovorode', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
