insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-skumbriya-v-tomate-s-ovoshchami', 'Скумбрия, тушённая в томате с овощами', 'Недорогая скумбрия в томатном соусе с морковью и перцем', 'main', array['lunch','dinner']::text[], 20, 40, 4, 2, 'fish', array['будни','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек разобрать, убрать кости и кожу. Порцию не перчить.', array['Лук нарезать полукольцами и обжарить на масле 3–4 минуты.','Добавить морковь брусочками или с крупной тёрки и жарить ещё 3–4 минуты, затем перец полосками — 2 минуты.','Положить томатную пасту, влить кипяток так, чтобы он покрыл овощи, размешать и посолить. Тушить на слабом огне 10–12 минут, пока морковь не станет мягкой.','Пока тушатся овощи, у скумбрии отрезать голову, выпотрошить, убрать тёмную плёнку, промыть и нарезать кусками.','Разложить рыбу по соусу, слегка утопив, и тушить под крышкой 7–10 минут.']::text[], 'https://www.iamcook.ru/showrecipe/23610', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
