insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kotlety-iz-rybnyh-konservov', 'Котлеты из рыбных консервов с рисом', 'Котлеты из консервов и риса — недорого и без разделки рыбы', 'main', array['lunch','dinner']::text[], 30, 45, 4, 2, 'fish', array['будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему фарш до перца. Его котлеты не жарить, а запечь на пергаменте 15–20 минут при 200 °C.', array['Рис промыть, всыпать в кипящую подсоленную воду и варить, пока вода не уйдёт с поверхности, затем 10 минут под крышкой на минимальном огне.','Лук мелко порубить, морковь натереть на мелкой тёрке и обжарить на 2 ст. л. масла около 5 минут. Остудить.','С консервов слить жидкость, убрать хребет и крупные кости, рыбу размять вилкой.','Смешать рыбу, тёплый рис, овощи, яйцо и базилик. Посолить, поперчить и понемногу подсыпать муку, пока фарш не начнёт держать форму.','Сформовать котлеты и обжарить на небольшом количестве масла до румяной корочки с обеих сторон.']::text[], 'https://www.gastronom.ru/recipe/56880/kotlety-iz-rybnyh-konservov-s-risom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
