insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-tvorozhnaya-zapekanka-s-syrom', 'Творожная запеканка с сыром и зеленью', 'Несладкая запеканка к ужину: творог, сыр и много зелени', 'main', array['lunch','dinner']::text[], 10, 40, 4, 2, 'cottage', array['будни','духовка']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит. Солить умеренно: в сыре уже есть соль.', array['Включить духовку на 180 °C. Творог размять вилкой с яйцами и щепоткой соли.','Сыр натереть, зелень мелко порубить и добавить к творогу.','Всыпать муку и перемешать до однородной массы.','Форму застелить пергаментом, смазать маслом, выложить массу и разровнять.','Запекать 20–25 минут до румяного верха. Дать постоять 5–10 минут, чтобы запеканка схватилась, нарезать и подать со сметаной.']::text[], 'https://www.iamcook.ru/showrecipe/22141', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
