insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-grechka-s-yaycom-i-ovoshchami', 'Гречка с яйцом и овощами под сыром', 'Гречка слоями с овощами и яйцом под сыром — сытно и без мяса', 'main', array['lunch','dinner']::text[], 20, 45, 4, 2, 'egg', array['будни','духовка','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит. Его порцию не перчить, яйцо порубить помельче.', array['Гречку промыть, залить кипятком, посолить и варить под крышкой около 20 минут до рассыпчатости. Одновременно сварить яйца вкрутую.','Лук нарезать, морковь натереть на крупной тёрке и обжарить на масле 3 минуты до мягкости.','Добавить помидоры мелкими кубиками и тушить ещё 3–4 минуты.','Включить духовку на 180 °C. Яйца очистить и нарезать кубиками, сыр натереть.','В смазанную форму выложить половину гречки, на неё половину овощей и яиц. Повторить слои и посыпать сыром.','Запекать около 15 минут до румяной сырной корочки. Подавать с петрушкой.']::text[], 'https://www.iamcook.ru/showrecipe/19214', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
