insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-makarony-s-brokkoli-i-syrom', 'Макароны с брокколи и сыром', 'Макароны, брокколи и тёртый сыр — ужин за 25 минут', 'main', array['lunch','dinner']::text[], 15, 25, 4, 1, 'dairy', array['быстро','будни','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит. Соцветия ему порезать мельче, порцию не перчить.', array['Сварить макароны в подсоленной воде по инструкции на упаковке, слить и заправить оливковым маслом.','Пока варятся макароны, брокколи разобрать на соцветия и отварить в подсоленном кипятке 4–5 минут. Крупные соцветия разрезать.','Сыр натереть.','Смешать горячие макароны с брокколи и сыром и перемешивать, пока сыр не расплавится.']::text[], 'https://www.iamcook.ru/showrecipe/5691', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
