insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kapustnye-kotlety-s-syrom', 'Капустные котлеты с сыром', 'Котлеты из тушёной капусты с сыром — дёшево и без мяса', 'main', array['lunch','dinner']::text[], 30, 45, 4, 2, 'dairy', array['будни','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его котлеты не жарить: запечь на пергаменте 15–20 минут при 200 °C. Перец не добавлять.', array['Капусту мелко нашинковать короткой соломкой.','Обжарить на слегка смазанной маслом сковороде 4–5 минут, помешивая. Посолить, добавить сметану и тушить ещё 5 минут.','Переложить капусту на широкую тарелку и полностью остудить, около 10 минут.','Вбить яйца, добавить натёртый сыр и муку, перемешать.','Мокрыми руками сформовать котлеты и обвалять в муке.','Обжарить на масле по 3–4 минуты с каждой стороны до румяной корочки.']::text[], 'https://www.iamcook.ru/showrecipe/33923', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
