insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-lenivaya-achma', 'Ленивая ачма из лаваша', 'Лаваш, творог и сыр в одной форме — как пирог, но без теста', 'main', array['lunch','dinner']::text[], 15, 45, 4, 2, 'cottage', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит. Солить по минимуму: сыр уже солёный.', array['Включить духовку на 180 °C. Творог размять с яйцами, влить молоко, слегка посолить и перемешать.','Сыр натереть на крупной тёрке и добавить к творогу.','Лаваш нарезать небольшими кусочками, добавить в миску и перемешать, чтобы он пропитался.','Выложить массу в форму, сверху разложить кусочки сливочного масла.','Запекать 30 минут до румяного верха. Дать постоять 5–7 минут и нарезать.']::text[], 'https://menunedeli.ru/recipe/lenivaya-achma-s-tvorogom-v-duxovke/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
