insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kuritsa-kusochkami-s-limonom', 'Курица кусочками с лимоном и чесноком', 'Целая курица кусками под лимоном: дешевле филе и почти без возни', 'main', array['lunch','dinner']::text[], 15, 45, 4, 2, 'poultry', array['будни','духовка','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Мясо снять с кости, кожу убрать, порезать мелко.', array['Включить духовку на 200 °C. Курицу разделать на 8–10 кусков: ножки разделить на бедро и голень, грудку разрезать на 4 части, отрезать крылья. Спинку можно заморозить для бульона.','Толстые места наколоть вилкой. Натереть куски солью, паприкой и чесноком через пресс.','Сложить курицу в миску, залить водой и оставить, пока греется духовка.','Противень с бортиками застелить фольгой и пергаментом, выложить курицу и вылить маринад вместе с чесноком.','На каждый кусок положить тонкий ломтик лимона. Запекать 30 минут; если сок у кости розовый, ещё 5 минут.']::text[], 'https://www.edimdoma.ru/retsepty/64368-kuritsa-v-marinade-s-limonom', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
