insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kuritsa-tushenaya-s-kapustoy', 'Курица, тушённая с капустой', 'Курица кусками с капустой в томате — сытно и недорого', 'main', array['lunch','dinner']::text[], 20, 45, 4, 3, 'poultry', array['будни','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Мясо снять с кости, кожу убрать, всё мелко порезать. Порцию отложить до перца.', array['Курицу разделать на небольшие куски, натереть солью и паприкой.','В широкой глубокой сковороде или сотейнике обжарить курицу на масле на сильном огне 2–3 минуты, переворачивая, до золотистой корочки.','Пока жарится мясо, нарезать лук и натереть морковь. Добавить к курице и жарить 2 минуты.','Нашинковать капусту полосками, выложить в сковороду и жарить 3–4 минуты, помешивая.','Развести томатную пасту водой, влить к курице и капусте, посолить. Тушить под крышкой на небольшом огне 30 минут, пока мясо не станет мягким.']::text[], 'https://www.iamcook.ru/showrecipe/23642', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
