insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kuritsa-v-smetane', 'Курица в сметане кусочками', 'Целая курица кусками, тушённая в сметане с луком и морковью', 'main', array['lunch','dinner']::text[], 20, 45, 4, 2, 'poultry', array['будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Мясо снять с кости, кожу убрать. Его порцию отложить до перца.', array['Курицу разрубить на небольшие куски и обсушить.','Лук нарезать четвертинками колец, морковь натереть на крупной тёрке.','На одной сковороде обжарить курицу на сильном огне до золотистой корочки, на другой — лук с морковью до мягкости, около 5 минут. Овощи переложить к курице.','Сметану размешать с кипятком, чтобы не свернулась, влить к курице и посолить.','Накрыть крышкой, убавить огонь и тушить 25 минут, пока мясо легко не отходит от кости. Взрослым поперчить в тарелке.']::text[], 'https://1000.menu/cooking/46387-kurica-tushenaya-v-kastrule-so-smetanoi-i-morkovu', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
