insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-gulyash', 'Гуляш из говядины', 'Мягкая говядина в томатной подливке — к пюре, гречке или макаронам', 'main', array['lunch','dinner']::text[], 30, 120, 4, 2, 'red-meat', array['выходные','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию до соли и перца, мясо нарезать мелко.', array['Говядину обсушить и нарезать кубиками 2–3 см, лук мелко порубить.','Обжарить мясо небольшими партиями на сильном огне до корочки и переложить в кастрюлю.','На той же сковороде обжарить лук до золотистого цвета, добавить томатную пасту, прогреть пару минут и переложить к мясу.','Залить кипятком так, чтобы мясо было покрыто на 2 см, положить лавровый лист и тушить под крышкой на слабом огне 1–1,5 часа до мягкости.','Муку подсушить на сухой сковороде до бежевого цвета и развести холодной водой без комков.','Влить муку в гуляш, дать закипеть и загустеть. Посолить и поперчить в самом конце.']::text[], 'https://www.gastronom.ru/recipe/59318/gulyash-iz-govyadiny-s-podlivkoj-kak-v-sssr', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
