insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-befstroganov', 'Бефстроганов', 'Тонкие полоски говядины в сметанном соусе, готово за полчаса', 'main', array['lunch','dinner']::text[], 25, 30, 4, 1, 'red-meat', array['быстро','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Часть полосок для Димы не жарить, а потушить 10 минут в соусе под крышкой; отложить до соли и перца, нарезать мельче.', array['Мясо нарезать поперёк волокон пластами около 2 см, отбить через плёнку до 1 см и нарезать полосками 3–4 см.','Растопить масло в глубокой сковороде и жарить мясо на среднем огне 7 минут, помешивая.','Сметану прогреть в сотейнике, вмешать муку и томатную пасту и держать на огне около минуты.','Залить мясо соусом, на слабом огне довести до кипения, посолить, поперчить и снять с огня.']::text[], 'https://www.gastronom.ru/recipe/15461/befstroganov-klassicheskij-iz-govjadiny-so-smetanoj', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
