insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-zharkoe', 'Жаркое с картошкой', 'Говядина, тушённая с картошкой и морковью, — сразу и мясо, и гарнир', 'main', array['lunch','dinner']::text[], 30, 120, 4, 2, 'red-meat', array['выходные','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию до соли и перца, мясо и картошку нарезать мелко или размять.', array['Говядину нарезать кубиками и обжарить в кастрюле с толстым дном до румяной корочки.','Добавить лавровый лист, немного воды и тушить под крышкой около 1,5 часа, подливая воду по мере выкипания.','Лук нарезать кубиком, морковь натереть на крупной тёрке и добавить к мясу.','Картофель нарезать средними кубиками, выложить в кастрюлю и залить водой вровень.','Тушить под крышкой ещё 30 минут до мягкости картошки, в конце посолить и поперчить.']::text[], 'https://www.edimdoma.ru/retsepty/147763-domashnee-zharkoe-iz-govyadiny', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
