insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-plov', 'Плов со свининой', 'Рассыпчатый плов в казане — на обед и на завтра', 'main', array['lunch','dinner']::text[], 30, 110, 4, 2, 'red-meat', array['выходные','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Воду для риса солить умеренно, перец только взрослым; Диме брать порцию сверху, без масла со дна, мясо нарезать мелко.', array['Свинину нарезать кусками одного размера и обжарить в казане без масла, пока не выпарится сок, затем добавить масло и довести до корочки.','Залить мясо горячей водой и тушить под крышкой на слабом огне 30 минут.','Рис промыть до прозрачной воды, морковь нарезать брусочками, лук полукольцами.','Когда вода выкипит, добавить лук и морковь и потомить 5 минут.','Разровнять сверху рис, не перемешивая, залить 600 мл горячей подсоленной воды и томить под крышкой на минимальном огне 30 минут.','Воткнуть в рис зубчики чеснока, томить ещё 10 минут, дать постоять 15 минут и перемешать.']::text[], 'https://www.edimdoma.ru/retsepty/39159-plov-so-svininoy', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
