insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-ragu-govyadina', 'Рагу с говядиной и овощами', 'Говядина с картошкой, кабачком и баклажаном, томлённые в духовке', 'main', array['lunch','dinner']::text[], 40, 165, 4, 2, 'red-meat', array['выходные','духовка','на 2–3 дня']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Отложить порцию до соли и перца, мясо и овощи нарезать мелко.', array['Разогреть духовку до 180 °C. Овощи нарезать крупными кубиками, чеснок измельчить.','Мясо нарезать кубиками, обвалять в муке и обжарить партиями в жаровне до корочки, отложить.','В той же посуде обжарить лук, затем добавить чеснок, баклажан, морковь и перец, в конце кабачок.','Влить 350 мл воды, добавить картофель, томатную пасту, лавровый лист и мясо, довести до кипения.','Накрыть крышкой и тушить в духовке около 2 часов, пока мясо не станет мягким. Посолить и поперчить в конце.']::text[], 'https://www.gastronom.ru/recipe/55249/ovoschnoe-ragu-s-mjasom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
