insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-svinina-smetana', 'Свинина в сметанном соусе', 'Кусочки свинины, тушённые в нежной сметане, — к любому гарниру', 'main', array['lunch','dinner']::text[], 20, 45, 4, 2, 'red-meat', array['будни','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию до соли и перца, кусочки нарезать мелко.', array['Свинину нарезать средними кусочками, чеснок мелко порубить.','Крахмал размешать в холодном молоке без комков и соединить со сметаной.','Разогреть оба масла и обжарить свинину на сильном огне до румяной корочки, в конце добавить чеснок на полминуты.','Убавить огонь, влить 250 мл горячей воды и тушить под крышкой 20 минут.','Влить сметанную смесь, перемешать и тушить ещё 10 минут на слабом огне. Посолить и поперчить.']::text[], 'https://1000.menu/cooking/40949-svinina-v-smetannom-souse-na-skovorode', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
