insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-otbivnye', 'Свиные отбивные', 'Отбивные в хрустящей панировке за полчаса', 'main', array['lunch','dinner']::text[], 25, 30, 4, 1, 'red-meat', array['быстро','будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме отбивную не солить и не перчить, запечь в духовке 20 минут при 200 °C и нарезать мелко.', array['Мясо нарезать порциями толщиной 2 см, завернуть в плёнку и отбить с обеих сторон.','Посолить, поперчить и натереть сушёными травами.','Яйца взбить с щепоткой соли и 2 ложками воды. Обвалять отбивные по очереди в муке, яйце и сухарях.','Разогреть на сковороде сливочное масло с растительным и жарить отбивные на среднем огне по 3–4 минуты с каждой стороны.','Проверить готовность надрезом: сок должен быть прозрачным.']::text[], 'https://www.gastronom.ru/recipe/60423/svinye-otbivnye-zharennye-v-panirovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
