insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-grechka-kupecheski', 'Гречка по-купечески', 'Гречка со свининой и овощами в одной сковороде — ужин без гарнира', 'main', array['lunch','dinner']::text[], 15, 40, 4, 2, 'red-meat', array['будни','бюджетное','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Солить умеренно, перец только взрослым в тарелку, мясо нарезать мелко.', array['Свинину нарезать небольшими кусочками и обжарить в глубокой сковороде на масле до золотистого цвета.','Лук мелко нарезать, морковь натереть, добавить к мясу и жарить пару минут.','Гречку промыть и разровнять поверх мяса.','Томатную пасту развести в 400 мл горячей воды, залить гречку, посолить и довести до кипения.','Накрыть крышкой и томить на слабом огне 15 минут, пока вода не впитается, затем перемешать.']::text[], 'https://1000.menu/cooking/18642-grechka-po-kupecheski-so-svininoi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
