insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-svinina-kabachok', 'Свинина с кабачком и перцем', 'Свинина, тушённая с овощами на сковороде, за 40 минут', 'main', array['lunch','dinner']::text[], 25, 40, 4, 1, 'red-meat', array['будни']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Отложить порцию до соли и перца, мясо нарезать мелко.', array['Лук, перец и кабачок нарезать кубиком, чеснок измельчить, свинину нарезать небольшими кусочками.','Обжарить лук на масле до прозрачности, добавить свинину и жарить до лёгкой корочки.','Добавить перец и готовить 3–4 минуты.','Добавить кабачок, через 6–7 минут влить 100 мл воды и тушить под крышкой 5–7 минут.','Открыть крышку, выпарить лишнюю жидкость, добавить чеснок и зелень, посолить и поперчить, прогреть пару минут.','Дать постоять под крышкой 5 минут.']::text[], 'https://www.iamcook.ru/showrecipe/39829', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
