insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-myaso-po-francuzski', 'Мясо по-французски', 'Свинина под картошкой, помидорами и сыром, со сметаной вместо майонеза', 'main', array['lunch','dinner']::text[], 20, 45, 4, 1, 'red-meat', array['будни','духовка','праздничное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Кусок для Димы не перчить; при подаче нарезать мелко.', array['Разогреть духовку до 200 °C. Свинину нарезать пластами около 1 см и отбить.','Картофель нарезать очень тонкими кружками, помидоры кружками, лук кольцами, сыр натереть.','Противень смазать маслом, выложить мясо, посолить, поперчить и накрыть луком.','Сверху выложить картофель, посолить и смазать половиной сметаны.','Выложить помидоры, посыпать сыром и смазать оставшейся сметаной.','Запекать 25–30 минут, пока картофель не станет мягким, а сыр не зарумянится.']::text[], 'https://1000.menu/cooking/232-myaso-po-frantsuzski', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
