insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kotlety', 'Котлеты домашние', 'Сочные котлеты из свино-говяжьего фарша с хлебом на молоке', 'main', array['lunch','dinner']::text[], 30, 45, 6, 2, 'red-meat', array['будни','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме слепить 2–3 котлеты до соли и перца и приготовить на пару или запечь 20 минут при 180 °C.', array['Мякиш хлеба замочить в молоке на 10 минут.','Лук и чеснок натереть или измельчить блендером.','Смешать фарш с луком, чесноком, отжатым хлебом и 3 ложками холодной воды, посолить и поперчить.','Отбивать фарш о миску 5 минут, чтобы котлеты держали форму.','Мокрыми руками сформовать толстые котлеты и обвалять в муке.','Обжарить на сильном огне до корочки с двух сторон, затем довести под крышкой на слабом огне 10 минут.']::text[], 'https://www.gastronom.ru/recipe/46071/domashnie-kotlety-na-skovorode', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
