insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-tefteli', 'Тефтели в томатном соусе', 'Тефтели с рисом, тушённые в томатной подливке, как в детском саду', 'main', array['lunch','dinner']::text[], 20, 45, 4, 2, 'red-meat', array['будни','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме скатать несколько тефтелей до перца и хмели-сунели; соус солить умеренно.', array['Рис отварить 10 минут до полуготовности, слить и остудить.','Пока варится рис, мелко нарезать лук и натереть морковь. Половину лука с морковью обжарить на масле в широкой кастрюле 5 минут.','Добавить томатную пасту и 500 мл воды, посолить и проварить 3 минуты.','Смешать фарш с оставшимся луком, рисом, солью, перцем и хмели-сунели, вымесить.','Скатать шарики размером с грецкий орех, обвалять в муке и опустить в кипящий соус.','Тушить под крышкой на слабом огне 25 минут.']::text[], 'https://www.gastronom.ru/recipe/48622/tefteli-s-risom-v-tomatnom-souse', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
