insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-makarony-flotski', 'Макароны по-флотски', 'Макароны с говяжьим фаршем и луком — ужин за 25 минут', 'main', array['lunch','dinner']::text[], 20, 25, 4, 1, 'red-meat', array['быстро','будни','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию до перца; фарш для Димы не зажаривать до корочки.', array['Отварить макароны в большом количестве подсоленной воды.','Мелко нарезать лук и обжарить на масле до лёгкой золотистости, в конце добавить измельчённый чеснок.','Сдвинуть лук к краю, выложить фарш и жарить на сильном огне 5 минут, разбивая комочки.','Добавить томатную пасту и 100 мл воды, посолить, поперчить и потомить под крышкой несколько минут.','Смешать с макаронами и дать постоять под крышкой пару минут. Посыпать зелёным луком.']::text[], 'https://menunedeli.ru/recipe/makarony-po-flotski/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
