insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-lenivye-golubcy', 'Ленивые голубцы', 'Вкус голубцов без заворачивания: котлетки с капустой и рисом в соусе', 'main', array['lunch','dinner']::text[], 20, 45, 4, 2, 'red-meat', array['будни','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме сформовать пару котлеток до перца; соус солить умеренно.', array['Рис сварить в 150 мл подсоленной воды за 10 минут и остудить.','Тем временем мелко нашинковать капусту и порубить лук, залить их кипятком на 10 минут, слить и отжать.','Смешать фарш, капусту с луком и рис, посолить и поперчить.','Сформовать продолговатые котлетки и уложить в широкую сковороду или сотейник.','Сметану смешать с томатной пастой и 200 мл воды, посолить и залить котлетки.','Тушить под крышкой на слабом огне 25 минут.']::text[], 'https://www.gastronom.ru/recipe/32392/lenivye-golubcy-v-duhovke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
