insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-golubcy', 'Голубцы', 'Классические голубцы с мясом и рисом в сметанно-томатном соусе', 'main', array['lunch','dinner']::text[], 90, 180, 4, 2, 'red-meat', array['выходные','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Для Димы свернуть первыми 1–2 голубца из начинки без перца; при подаче нарезать мелко.', array['Кочан опускать в кипяток и снимать размягчённые листья партиями, по 5 минут на партию. Срезать с листьев утолщения.','Рис промыть, залить 150 мл воды, варить 10 минут и дать постоять под крышкой.','Лук мелко нарезать, морковь натереть и обжарить на масле 7–8 минут.','Смешать фарш, рис, обжаренные овощи, тёртые помидоры без кожицы и рубленый укроп, посолить и поперчить.','Завернуть начинку в листья и плотно уложить в кастрюлю, дно которой выстлано листьями.','Смешать сметану, томатную пасту и 600 мл воды, посолить и залить голубцы. Прижать тарелкой и тушить на слабом огне 1–1,5 часа.']::text[], 'https://menunedeli.ru/recipe/golubcy-recept-s-risom-i-farshem-klassicheskij/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
