insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-percy-farshirovannye', 'Перцы, фаршированные мясом и рисом', 'Болгарский перец с мясом и рисом, тушённый в сметанно-томатном соусе', 'main', array['lunch','dinner']::text[], 35, 90, 4, 2, 'red-meat', array['выходные','на 2–3 дня']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Диме нафаршировать 1 перец начинкой без перца; с перца снять кожицу, начинку размять.', array['У перцев срезать плодоножки, удалить семена и перегородки.','Рис отварить до полуготовности и остудить.','Лук мелко нарезать, морковь натереть, обжарить на масле до мягкости и остудить.','Смешать фарш, рис, половину овощей, соль и перец. Плотно нафаршировать перцы.','Оставшиеся овощи выложить на дно кастрюли и поставить сверху перцы. Сметану смешать с томатной пастой и 500 мл тёплой воды и залить перцы.','Довести до кипения и тушить под крышкой на слабом огне 35–40 минут.']::text[], 'https://1000.menu/cooking/397-percy-farshirovannye-myasom-i-risom-v-kastrule', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
