insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-ezhiki', 'Ёжики', 'Мясные шарики с рисом в сметанно-томатном соусе, без жарки', 'main', array['lunch','dinner']::text[], 15, 40, 4, 2, 'red-meat', array['будни','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'ok', 'Фарш и соус солить умеренно.', array['Лук мелко нарезать и обжарить на масле до мягкости.','Смешать фарш с луком, сырым рисом и яйцом, посолить.','Морковь нарезать соломкой и обжарить на масле в глубокой сковороде.','Томаты пюрировать и смешать с томатной пастой, сметаной и мукой до однородности, влить 200 мл воды и посолить.','Скатать шарики, уложить на морковь и залить соусом так, чтобы он их покрыл.','Довести до кипения, убавить огонь до минимума и тушить под крышкой 30 минут.']::text[], 'https://www.iamcook.ru/showrecipe/7668', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
