insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kapusta-s-farshem', 'Тушёная капуста с фаршем', 'Капуста с мясным фаршем и томатом — сытно и недорого', 'main', array['lunch','dinner']::text[], 25, 45, 4, 2, 'red-meat', array['будни','бюджетное','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию до перца; капусту для Димы тушить до полной мягкости.', array['Капусту нашинковать, посолить, помять руками и оставить на 10 минут.','Лук мелко нарезать, морковь натереть и обжарить в сотейнике на масле 5 минут.','Добавить фарш и жарить 5–7 минут, разбивая комки, до лёгкого румянца.','Отжать капусту от сока, переложить к фаршу и прожарить 5 минут.','Добавить томатную пасту, измельчённый чеснок, травы и 150 мл воды и тушить под крышкой на слабом огне 20 минут.','Попробовать, досолить, поперчить и при желании добавить щепотку сахара.']::text[], 'https://www.gastronom.ru/recipe/59798/tushennaya-kapusta-s-farshem-na-skovorodke', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
