insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-zapekanka-kartofelnaya', 'Картофельная запеканка с фаршем', 'Пюре и мясной фарш слоями под сырной корочкой', 'main', array['lunch','dinner']::text[], 30, 70, 4, 2, 'red-meat', array['духовка','детское','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'ok', 'Солить умеренно; из специй только базилик.', array['Картофель очистить и сварить в подсоленной воде за 20–25 минут.','Тем временем лук мелко нарезать и обжарить на масле, добавить фарш и готовить, помешивая, до серого цвета. Посолить и добавить базилик.','Слить воду, размять картофель с тёплым молоком, вмешать сливочное масло и яйцо.','Разогреть духовку до 180 °C, натереть сыр, смазать форму маслом.','Выложить половину пюре, сверху фарш, затем остальное пюре и посыпать сыром.','Запекать 20–25 минут до румяной корочки.']::text[], 'https://1000.menu/cooking/3772-zapekanka-iz-kartofelnogo-pure-v-duxovke-s-farshem', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
