insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-spagetti-boloneze', 'Спагетти болоньезе', 'Спагетти с мясным соусом из говяжьего фарша, овощей и томатов', 'main', array['lunch','dinner']::text[], 25, 45, 4, 1, 'red-meat', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить Диме соус до соли и перца, спагетти поломать или нарезать.', array['Лук и чеснок мелко нарезать и обжарить на масле до прозрачности.','Добавить тёртую морковь и мелко нарезанный сельдерей и тушить на слабом огне 10 минут.','Выложить фарш и готовить 10 минут, разбивая комки.','Добавить томаты, размять их и тушить 15 минут. В конце посолить и поперчить.','Тем временем отварить спагетти и слить воду.','Разложить спагетти по тарелкам, сверху соус и тёртый сыр.']::text[], 'https://www.edimdoma.ru/retsepty/124015-pasta-bolonieze', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
