insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-ragu-fasol', 'Овощное рагу с фасолью', 'Постное рагу из перца, кабачка и двух видов фасоли в томатах', 'main', array['lunch','dinner']::text[], 15, 45, 4, 2, 'legume', array['будни','постное','бюджетное','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию до соли и перца, фасоль размять вилкой. Бобовые — не чаще 2–3 раз в неделю.', array['Перец и кабачок нарезать кубиками, морковь четвертинками, лук и чеснок мелко порубить.','Обжарить лук с чесноком на масле 2–3 минуты.','Добавить перец, морковь и кабачок и тушить 5 минут до мягкости.','Добавить фасоль, томаты и орегано и тушить под крышкой на слабом огне 25 минут.','Посолить, поперчить и при желании добавить щепотку сахара.']::text[], 'https://menunedeli.ru/recipe/ovoshhnoe-ragu-s-fasolyu/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
