insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-chechevica', 'Чечевица с овощами', 'Красная чечевица, тушённая с овощами, — постный ужин за 40 минут', 'main', array['lunch','dinner']::text[], 20, 40, 4, 2, 'legume', array['будни','постное','бюджетное','на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию до соли и перца. Бобовые — не чаще 2–3 раз в неделю.', array['Лук и морковь мелко нарезать и обжарить на масле до мягкости, добавить чеснок на минуту.','Добавить нарезанный перец и готовить 2–3 минуты.','Положить нарезанные помидоры и томаты из банки, потушить пару минут, затем добавить кабачок кубиками.','Всыпать промытую чечевицу, паприку и куркуму, перемешать и прогреть 2 минуты.','Влить 400 мл воды, довести до кипения и тушить на слабом огне 15 минут. Посолить и поперчить в конце.','Подавать, посыпав зеленью.']::text[], 'https://www.iamcook.ru/showrecipe/29808', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
