insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-zapekanka-cvetnaya', 'Запеканка из цветной капусты с сыром', 'Цветная капуста в яично-сметанной заливке под сырной корочкой', 'main', array['lunch','dinner']::text[], 15, 45, 4, 1, 'egg', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Соцветия для Димы разрезать помельче.', array['Капусту разобрать на соцветия и отварить в подсоленной воде 7–8 минут, остудить под холодной водой.','Разогреть духовку до 180 °C. Зелень и чеснок мелко порубить, сыр натереть.','Яйца взбить со сметаной, слегка посолить, вмешать половину сыра, зелень и чеснок.','Форму смазать маслом, выложить капусту и залить яичной массой.','Посыпать оставшимся сыром и запекать 25–30 минут до румяной корочки.']::text[], 'https://menunedeli.ru/recipe/zapekanka-iz-cvetnoj-kapusty-v-duxovke-s-syrom-i-yajcom/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
