insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-zapekanka-kabachki', 'Кабачки в яично-сырной заливке', 'Кабачки с помидорами в сырно-яичной заливке, на сковороде под крышкой', 'main', array['lunch','dinner']::text[], 20, 40, 4, 1, 'egg', array['будни','детское']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Помидоры для Димы лучше очистить от кожицы.', array['Кабачок нарезать кубиком, посолить, оставить на 10 минут и отжать. Помидоры нарезать.','Натереть сыр. Сметану смешать с мукой, яйцами и половиной сыра, посолить.','Кабачок потушить на масле под крышкой 5 минут, добавить помидоры и готовить ещё 5 минут.','Залить овощи яичной смесью, убавить огонь, накрыть крышкой и готовить 10–12 минут.','Посыпать оставшимся сыром, снять с огня и подержать под крышкой 5–10 минут. Посыпать зеленью.']::text[], 'https://1000.menu/cooking/38912-zapekanka-iz-kabachkov-na-skovorode-s-yaicom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
