insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-zapekanka-makaronnaya', 'Макаронная запеканка с сыром', 'Макароны в яично-молочной заливке с двумя сырами', 'main', array['lunch','dinner']::text[], 15, 35, 4, 1, 'dairy', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Солить заливку умеренно.', array['Макароны отварить в подсоленной воде до полуготовности, слить и немного остудить.','Натереть оба сыра, яйца взбить с молоком и солью. Разогреть духовку до 180 °C.','Смешать макароны с большей частью сыра, оставив горсть моцареллы.','Выложить в смазанную маслом форму и залить яично-молочной смесью.','Посыпать сухарями и твёрдым сыром и запекать 15 минут.','Перед подачей посыпать оставшейся моцареллой.']::text[], 'https://www.iamcook.ru/showrecipe/9776', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
