insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-vareniki-kartofel', 'Вареники с картошкой', 'Домашние вареники с картошкой и жареным луком, со сметаной', 'main', array['lunch','dinner']::text[], 70, 80, 4, 1, 'none', array['выходные','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме без жареного лука сверху, со сметаной; вареники разрезать.', array['Картофель нарезать брусочками и сварить в подсоленной воде с лавровым листом за 15 минут.','Лук мелко нарезать и спассеровать на масле до золотистого цвета.','Слить воду, размять картофель, вмешать две трети лука и остудить.','Замесить крутое тесто из муки, 150 мл воды, яйца и щепотки соли, убрать в пакет на 30 минут.','Скатать тесто колбаской, нарезать кусочками, раскатать кружки, положить начинку и защипнуть края.','Варить в кипящей подсоленной воде 4 минуты после всплытия и смешать с оставшимся луком.']::text[], 'https://menunedeli.ru/recipe/vareniki-s-kartoshkoj-recept-klassicheskij/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
