insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-zrazy-kartofelnye', 'Картофельные зразы с яйцом и луком', 'Картофельные котлетки с начинкой из яйца и лука, со сметаной', 'main', array['lunch','dinner']::text[], 40, 75, 4, 1, 'egg', array['выходные','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Диме зразы не жарить, а запечь на пергаменте 20 минут при 200 °C.', array['Картофель очистить и сварить в подсоленной воде до мягкости. Четыре яйца сварить вкрутую.','Размять картофель со сливочным маслом, остудить и вмешать сырое яйцо.','Лук мелко нарезать, обжарить до прозрачности и смешать с рублеными яйцами, посолить.','Из пюре сделать лепёшки, положить начинку, защипнуть края и придать форму котлеты.','Обвалять в муке и обжарить на масле до румяной корочки с двух сторон.','Подавать со сметаной.']::text[], 'https://1000.menu/cooking/3823-zrazj-kartofelnje', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
