insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kuritsa-s-kartoshkoy', 'Курица с картошкой в духовке', 'Бёдра и картошка в одной форме: гарнир печётся вместе с мясом', 'main', array['lunch','dinner']::text[], 15, 60, 4, 2, 'poultry', array['духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусок отложить до соли и перца и запечь рядом. Кожу снять, мясо снять с кости и нарезать.', array['Включить духовку на 180 °C. Бёдра вымыть, обсушить, срезать лишний жир.','Картошку почистить и нарезать кубиками среднего размера, лук — дольками.','Сложить курицу и картошку в миску, добавить рубленый чеснок, паприку, соль и перец, перемешать. Пусть постоит, пока греется духовка.','Переложить всё в форму, разложить лук и полить маслом.','Запекать 40 минут, пару раз полив соком со дна формы.','Поднять температуру до 200 °C и подрумянить ещё 5–7 минут.']::text[], 'https://1000.menu/cooking/35826-kurinye-bedryshki-s-kartoshkoi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
