insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurinye-kotlety', 'Рубленые куриные котлеты', 'Сочные котлеты из филе, нарезанного ножом, — мясорубка не нужна', 'main', array['lunch','dinner']::text[], 25, 40, 4, 3, 'poultry', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Часть массы отложить до перца и не жарить: выложить ложкой на пергамент и запечь 20 минут при 190 °C.', array['Филе нарезать ножом мелким кубиком, примерно по полсантиметра.','Добавить яйцо, сметану, муку, мелко рубленый чеснок и соль, перемешать. Дать постоять 15 минут.','Разогреть сковороду с маслом. Выкладывать массу столовой ложкой и слегка приплющивать.','Жарить на среднем огне по 4–5 минут с каждой стороны до румяной корочки.','Накрыть крышкой, убавить огонь и подержать ещё 5 минут.']::text[], 'https://1000.menu/cooking/34465-kurinye-kotlety-nejnye', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
