insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kotlety-iz-indeyki-na-paru', 'Котлеты из индейки на пару', 'Нежные паровые котлеты с картошкой в фарше — без жарки и масла', 'main', array['lunch','dinner']::text[], 25, 45, 4, 3, 'poultry', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Паровые котлеты подходят. Перец в фарш не класть, солить умеренно.', array['Залить сухари молоком, чтобы набухли.','Индейку, картошку и лук нарезать крупно и прокрутить через мясорубку. Для нежности — два раза.','Добавить сухари с молоком, яйцо, рубленую петрушку и соль. Хорошо вымешать.','Мокрыми руками слепить котлеты и выложить на решётку пароварки или мультиварки.','Готовить на пару 20–25 минут.']::text[], 'https://1000.menu/cooking/14545-kotlety-iz-indeiki-na-paru', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
