insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-bedra-v-smetane-s-syrom', 'Куриные бёдра в сметане с сыром', 'Бёдра под сметаной и сырной корочкой: пять минут работы, остальное — духовка', 'main', array['lunch','dinner']::text[], 10, 45, 4, 2, 'poultry', array['будни','духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Кожу снять, мясо снять с кости и нарезать мелко. Его кусок не перчить.', array['Включить духовку на 180 °C. Бёдра вымыть, обсушить, посолить и поперчить.','Перемешать курицу со сметаной и выложить в форму.','Сыр натереть на крупной тёрке и посыпать сверху.','Запекать до румяной корочки: бёдра без кости — около 30 минут, на кости — около 40.']::text[], 'https://1000.menu/cooking/30397-kurinye-bedra-v-smetane', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
