insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-grudka-v-slivochnom-souse', 'Куриная грудка в сливочном соусе', 'Кусочки грудки, тушённые с луком в сливках с чесноком', 'main', array['lunch','dinner']::text[], 20, 35, 4, 2, 'poultry', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Тушёная курица подходит. Солить умеренно, кусочки для него нарезать мельче.', array['Филе нарезать крупными кусками, лук — мелко.','Обжарить курицу на горячей сковороде с маслом по 2–3 минуты с каждой стороны.','Добавить лук, посолить, приправить. Накрыть крышкой и тушить на слабом огне 10–15 минут.','Муку размешать в 150 мл холодной воды, чеснок измельчить.','Влить к курице сливки и воду с мукой, добавить чеснок. Довести до кипения и прогреть, пока соус не загустеет.']::text[], 'https://1000.menu/cooking/35020-file-kurinoe-v-slivochnom-souse-na-skovorode', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
