insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kuritsa-tushenaya-s-ovoshchami', 'Курица, тушённая с овощами', 'Курица с картошкой, кабачком и капустой в одной сковороде — сразу с гарниром', 'main', array['lunch','dinner']::text[], 25, 45, 4, 3, 'poultry', array['будни','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Мясо снять с кости, всё нарезать мелко. Его порцию отложить до досаливания.', array['Курицу нарезать кусками и обжарить на масле в глубокой сковороде или сотейнике до светлой корочки.','Добавить нарезанные лук и морковь, жарить ещё 3–4 минуты.','Картошку нарезать крупно, капусту нашинковать, кабачок нарезать кубиками. Выложить всё к курице.','Влить 500 мл горячей воды, посолить, приправить.','Тушить под крышкой 20–25 минут, пока курица не приготовится, а картошка не станет мягкой. В конце добавить рубленый чеснок.']::text[], 'https://1000.menu/cooking/66150-ovoschnoe-ragu-s-kuricei-i-kabachkami', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
