insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurinye-tefteli-v-slivochnom-souse', 'Куриные тефтели в сливочном соусе', 'Тефтели из курицы, запечённые в сливочном соусе под сыром', 'main', array['lunch','dinner']::text[], 30, 60, 4, 3, 'poultry', array['духовка','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Часть фарша отложить до перца. Его тефтели не обжаривать, а сразу положить в форму — пропекутся в соусе.', array['Лук и чеснок крупно нарезать и вместе с курицей измельчить в блендере или мясорубке. Посолить, добавить паприку и перец, перемешать.','Слепить шарики чуть больше грецкого ореха.','Обжарить тефтели на масле со всех сторон до румяности и переложить в форму. Включить духовку на 180 °C.','Для соуса слегка подсушить муку на сухой сковороде, добавить сливочное масло и растопить.','Влить сливки, мешая венчиком, и прогреть до лёгкого загустения. Посолить.','Залить тефтели соусом, посыпать тёртым сыром и запекать 30 минут.']::text[], 'https://www.gastronom.ru/recipe/56088/kurinye-tefteli-v-slivochnom-souse', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
