insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kuritsa-s-risom-v-duhovke', 'Курица с рисом в духовке', 'Рис пропитывается соком курицы — мясо и гарнир готовы в одной форме', 'main', array['lunch','dinner']::text[], 15, 60, 4, 2, 'poultry', array['духовка','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Мясо снять с кости, кожу убрать. Его порцию отложить до досаливания.', array['Включить духовку на 180 °C. Рис промыть несколько раз и выложить ровным слоем в форму.','Томатную пасту размешать в 500 мл воды и залить рис.','Курицу нарезать кусками и уложить на рис, слегка вдавливая. Сверху — кружочки моркови и чеснок через пресс. Посолить, приправить.','Накрыть форму фольгой и запекать 20 минут.','Снять фольгу, смазать курицу маслом и запекать ещё 20–30 минут, пока рис не станет мягким, а курица не подрумянится.']::text[], 'https://1000.menu/cooking/44358-ris-s-kuricei-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
