insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-gulyash-iz-indeyki', 'Гуляш из индейки', 'Индейка в томатно-сметанной подливке — к гречке, пюре или макаронам', 'main', array['lunch','dinner']::text[], 15, 45, 4, 3, 'poultry', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Тушёное мясо подходит. Перец не добавлять, кусочки для него нарезать мельче.', array['Индейку нарезать кусочками среднего размера.','Обжарить на разогретом масле, помешивая, до светлой корочки.','Всыпать муку и жарить, помешивая, ещё 2 минуты.','Добавить томатную пасту и сметану, влить 200 мл горячей воды, посолить, добавить паприку и перемешать.','Накрыть крышкой и тушить на самом слабом огне 30 минут, пока мясо не станет мягким.']::text[], 'https://1000.menu/cooking/26798-gulyash-iz-indeiki-s-podlivkoi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
