insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurinye-otbivnye', 'Куриные отбивные в кляре', 'Тонкие отбивные в пышном кляре на взбитых белках', 'main', array['lunch','dinner']::text[], 30, 35, 4, 2, 'poultry', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек отбить, без кляра и перца, и запечь на пергаменте 15–20 минут при 190 °C или приготовить на пару.', array['Филе разрезать вдоль на пласты толщиной около сантиметра и отбить через плёнку. Посолить и поперчить.','Отделить белки от желтков. Желтки взбить с ложкой холодной воды, белки — со щепоткой соли в пышную пену.','Каждый пласт обмакнуть в желтки, обвалять в муке, затем окунуть во взбитые белки.','Жарить на разогретом масле на среднем огне по 3–4 минуты с каждой стороны до золотистого цвета.']::text[], 'https://1000.menu/cooking/40842-kurinye-otbivnye-na-skovorode', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
