insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-goleni-v-medovo-soevom-souse', 'Голени в медово-соевом соусе', 'Голени в глянцевой глазури из мёда и соевого соуса', 'main', array['lunch','dinner']::text[], 15, 90, 4, 2, 'poultry', array['духовка','выходные','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Соевый соус малышу нельзя: одну голень отложить до маринада и запечь рядом в фольге с каплей масла. Кожу снять, мясо снять с кости.', array['Смешать соевый соус, 1 ст. л. мёда, чеснок через пресс, лимонный сок, 2 ст. л. масла, паприку и перец.','Голени обсушить, залить маринадом, перемешать и оставить на 30–40 минут.','Разогреть духовку до 180 °C, форму смазать оставшимся маслом. Выложить голени в один слой и полить маринадом.','Накрыть фольгой и запекать 30 минут. Проколоть самую толстую голень: если сок не прозрачный — ещё 10 минут.','Снять фольгу, смазать голени оставшимся мёдом, поднять температуру до 210 °C и запекать ещё 10 минут до глянцевой корочки.']::text[], 'https://www.gastronom.ru/recipe/91/kurinaya-golen-v-medovom-souse', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
