insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kartofelnaya-zapekanka-s-kurinym-farshem', 'Картофельная запеканка с куриным фаршем', 'Картошка, морковь и фарш слоями под сметанно-сырной заливкой', 'main', array['lunch','dinner']::text[], 25, 70, 4, 2, 'poultry', array['духовка','детское','выходные']::text[], array['any']::text[], '{}'::text[], 'ok', 'Запеканка подходит. Перец в фарш не класть, солить умеренно.', array['Лук натереть на мелкой тёрке, петрушку порубить. Смешать с фаршем и посолить.','Картошку и морковь нарезать тонкими кружочками, посолить, приправить травами и полить маслом.','В смазанную форму выложить половину овощей, сверху ровным слоем фарш, затем остальные овощи.','Накрыть фольгой и запекать при 190 °C 35–40 минут, пока картошка не станет мягкой.','Взбить сметану с яйцом и тёртым сыром. Снять фольгу, залить запеканку, сверху разложить кружочки помидора.','Запекать без фольги ещё 10 минут до румяного верха.']::text[], 'https://1000.menu/cooking/19469-zapekanka-kartofel-s-kurinym-farshem-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
