insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurinaya-grudka-s-pomidorami-v-folge', 'Куриная грудка с помидорами в фольге', 'Филе в сметане с ломтиками помидора, запечённое в фольге, — сочно и без жарки', 'main', array['lunch','dinner']::text[], 15, 40, 4, 2, 'poultry', array['будни','духовка']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит: перец только взрослым в тарелку, его кусок нарезать мелко.', array['Разогреть духовку до 200 °C. Смешать сметану, раздавленный чеснок, паприку и соль.','На каждом филе сделать несколько поперечных надрезов, не прорезая до конца.','Смазать филе сметанной смесью и оставить на 10–15 минут.','Помидоры нарезать полукружьями и вложить в надрезы.','Каждое филе плотно завернуть в фольгу и запекать 25 минут. Проколоть: сок должен быть прозрачным. Взрослым поперчить в тарелке.']::text[], 'https://www.iamcook.ru/showrecipe/13531', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
