insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-kurinoe-sufle-na-paru', 'Куриное суфле на пару', 'Воздушное суфле из куриного филе — как в детском саду, только вкуснее', 'main', array['lunch','dinner']::text[], 20, 40, 4, 2, 'poultry', array['будни','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит как есть. Солить умеренно.', array['Филе нарезать кусочками и измельчить в блендере или комбайне до однородности.','Добавить яйца и соль, снова взбить. Всыпать манку и перемешать.','Добавить сметану и хорошо взбить: чем дольше, тем воздушнее суфле.','Формочки смазать маслом и заполнить массой на две трети — суфле поднимется.','Готовить на пару 20–25 минут.']::text[], 'https://1000.menu/cooking/15337-kurinoe-sufle-na-paru', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
