insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-makarony-s-kuritsey-i-brokkoli', 'Макароны с курицей и брокколи', 'Макароны в сливочном соусе с курицей и брокколи за полчаса', 'main', array['lunch','dinner']::text[], 25, 30, 4, 2, 'poultry', array['быстро','будни','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит: курицу и брокколи ему порезать мельче, перец только взрослым в тарелку.', array['Макароны отварить в подсоленной воде по инструкции на пачке и откинуть.','Курицу нарезать небольшими кусочками и обжарить на масле до светлой корочки.','Добавить соцветия брокколи и мелко нарезанный чеснок, готовить 3–4 минуты.','Влить сливки, посолить и потушить 2–3 минуты.','Посыпать рубленой петрушкой и тёртым сыром, добавить макароны и перемешать.']::text[], 'https://1000.menu/cooking/11776-pasta-v-slivochnom-souse-s-brokkoli', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
