insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-mintay-tushenyy-s-morkovyu', 'Минтай, тушённый с морковью и луком', 'Дешёвая рыба в томатной подливке с овощами, без жарки', 'main', array['lunch','dinner']::text[], 15, 35, 4, 2, 'fish', array['будни','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек разобрать и убрать все кости. С филе проще.', array['Минтай разморозить, почистить и нарезать порционными кусками.','Лук нарезать мелким кубиком, морковь натереть.','Обжарить овощи на масле до мягкости лука, добавить томатную пасту и паприку, перемешать.','Выложить рыбу на овощи, посолить и влить 200 мл воды.','Тушить под крышкой на слабом огне 15–20 минут.']::text[], 'https://1000.menu/cooking/31633-mintai-tushenyi-na-skovorode-s-lukom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
