insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-rybnye-kotlety-iz-mintaya', 'Рыбные котлеты из минтая в духовке', 'Нежные котлеты из минтая без жарки — дети едят охотно', 'main', array['lunch','dinner']::text[], 25, 55, 4, 2, 'fish', array['духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Котлеты без жарки подходят. Перец в фарш не класть.', array['Хлеб залить молоком на 10 минут, затем отжать.','Филе проверить на мелкие кости и измельчить в блендере.','Добавить хлеб, яйца, растопленное масло, чеснок через пресс и соль, вымесить. Если фарш жидкий, всыпать 1–2 ст. л. манки и дать постоять 10 минут.','Слепить небольшие котлеты, обвалять в манке и выложить на противень с пергаментом.','Запекать при 180 °C 30–35 минут.']::text[], 'https://1000.menu/cooking/21498-rybnye-kotlety-iz-mintaya-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
