insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-treska-v-smetane', 'Треска в сметане', 'Треска, запечённая в сметанно-яичной заливке с укропом', 'main', array['lunch','dinner']::text[], 10, 50, 4, 2, 'fish', array['духовка']::text[], array['any']::text[], '{}'::text[], 'adapt', 'В стейке хребтовая кость: его кусочек разобрать и проверить на кости. Перец только взрослым в тарелку.', array['Включить духовку на 180 °C. Укроп мелко порубить.','Взбить яйца с молоком, добавить половину укропа и соль.','Вылить смесь в смазанную маслом форму и уложить стейки. Рыба не должна полностью тонуть.','Посолить рыбу, посыпать оставшимся укропом и распределить сверху сметану.','Запекать 35–40 минут.']::text[], 'https://1000.menu/cooking/23340-treska-v-smetane-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
