insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-gorbusha-v-folge', 'Горбуша в фольге', 'Недорогая красная рыба: стейки в фольге с лимоном и травами', 'main', array['lunch','dinner']::text[], 10, 40, 4, 2, 'fish', array['будни','духовка']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его стейк не перчить; перед подачей снять кожу и выбрать кости.', array['Включить духовку на 180 °C. Стейки промыть и обсушить.','Полить рыбу маслом и лимонным соком, посыпать базиликом, чесноком и солью. Поперчить все стейки, кроме Диминого.','Выложить стейки на лист фольги, между ними разложить лавровый лист.','Накрыть вторым листом фольги и плотно завернуть края, чтобы сок не вытекал.','Запекать 25–30 минут.']::text[], 'https://1000.menu/cooking/66624-gorbusha-v-duxovke-sochnaya-v-folge-kusochkami', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
