insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-hek-v-klyare', 'Хек в кляре', 'Филе хека в сметанном кляре — быстро и без костей', 'main', array['lunch','dinner']::text[], 20, 30, 4, 1, 'fish', array['быстро','будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек не жарить: без кляра и перца запечь в фольге 15 минут при 190 °C или приготовить на пару.', array['Филе нарезать порционными кусками, посолить, поперчить и оставить на 10 минут.','Для кляра взбить яйца со сметаной и мукой до однородности, слегка посолить.','Разогреть сковороду с маслом. Обмакивать рыбу в кляр и выкладывать на сковороду.','Жарить на среднем огне по 3–4 минуты с каждой стороны до золотистого цвета.','Выложить на бумажное полотенце, чтобы стекло лишнее масло.']::text[], 'https://1000.menu/cooking/17730-file-xeka-v-klyare', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
