insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-ryba-po-polski', 'Рыба по-польски', 'Отварной минтай под соусом из сливочного масла, яиц и зелени', 'main', array['lunch','dinner']::text[], 25, 35, 4, 2, 'fish', array['будни','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек проверить на мелкие кости.', array['Вскипятить в кастрюле воду с лавровым листом и солью.','Филе нарезать порционными кусками, опустить в кипяток и варить 3 минуты после закипания. Вынуть, бульон не выливать.','Яйца сварить вкрутую, очистить и мелко порубить. Зелень порубить.','Растопить сливочное масло, всыпать муку и перемешать. Добавить яйца и прогреть, помешивая.','Понемногу вливать бульон, размешивая, пока соус не станет густым, как сметана.','Снять с огня, добавить зелень и лимонный сок. Полить рыбу соусом.']::text[], 'https://1000.menu/cooking/22916-ryba-po-polski-s-yaicom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
