insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-skumbriya-s-morkovyu-i-lukom', 'Скумбрия, запечённая с морковью и луком', 'Филе скумбрии под овощной шубкой — сочная рыба без хребта и костей', 'main', array['lunch','dinner']::text[], 30, 55, 4, 2, 'fish', array['духовка']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек без кожи; перед подачей ещё раз проверить на мелкие косточки.', array['Морковь натереть, лук нарезать мелко. Обжарить морковь на масле до мягкости, добавить лук и жарить ещё 2–3 минуты. Остудить.','Скумбрии отрезать голову и хвост, разрезать по брюшку, выпотрошить, убрать тёмную плёнку, вынуть хребет и кости, промыть и обсушить.','Выложить филе кожей вниз на противень с пергаментом, сбрызнуть лимонным соком, посолить, приправить.','Смазать тонким слоем сметаны и распределить сверху овощи.','Запекать при 180 °C 20–25 минут.']::text[], 'https://1000.menu/cooking/16795-skumbriya-zapechennaya-s-lukom-i-morkovu-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
