insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-rybnaya-zapekanka-s-kartofelem', 'Рыбная запеканка с картошкой', 'Минтай, картошка и лук слоями под сметаной и сыром — ужин в одной форме', 'main', array['lunch','dinner']::text[], 20, 60, 4, 2, 'fish', array['духовка','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его кусочек проверить на кости, солить умеренно.', array['Картошку нарезать тонкими кружочками, лук — мелким кубиком. Сметану смешать с рубленым укропом и посолить.','Форму смазать маслом, выложить половину картошки, смазать двумя ложками соуса и посыпать половиной лука.','Сверху уложить рыбу, посолить и сбрызнуть лимонным соком.','Добавить остальной лук и картошку, залить оставшимся соусом.','Посыпать тёртым сыром и запекать при 180 °C 40 минут, пока картошка не станет мягкой.']::text[], 'https://www.edimdoma.ru/retsepty/132294-rybno-kartofelnaya-zapekanka', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
