insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-rybnye-tefteli-v-tomatnom-souse', 'Рыбные тефтели в томатном соусе', 'Тефтели из минтая с овсянкой, томлённые в томатном соусе без жарки', 'main', array['lunch','dinner']::text[], 30, 70, 4, 3, 'fish', array['духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Тефтели не жарятся — подходят. Перец в фарш не класть, лавровый лист вынуть.', array['Филе очистить от кожи и костей и измельчить в блендере вместе со сливочным маслом, овсяными хлопьями, яйцом и солью.','Слепить шарики и обвалять в муке.','Лук нарезать, морковь натереть и обжарить на растительном масле до мягкости. Добавить томатную пасту, посолить, влить немного кипятка и прогреть 5 минут.','Выложить соус в толстостенную форму или кастрюлю, сверху — тефтели. Подлить кипятка почти до верха тефтелей, добавить чеснок и лавровый лист.','Запекать при 180 °C 40 минут. Подавать с рубленым укропом.']::text[], 'https://1000.menu/cooking/22970-rybnye-tefteli-v-tomatnom-souse', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
