insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-semga-s-ovoshchami-v-folge', 'Сёмга с овощами в фольге', 'Стейки сёмги с помидорами и перцем в фольге — просто и по-праздничному', 'main', array['lunch','dinner']::text[], 15, 45, 4, 1, 'fish', array['духовка','праздничное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Его стейк не перчить; перед подачей снять кожу и выбрать кости.', array['Стейки промыть, сбрызнуть лимонным соком и посолить; все, кроме Диминого, поперчить. Оставить на 15 минут.','Помидоры и перец нарезать. Включить духовку на 200 °C.','На каждый лист фольги выложить часть овощей, сверху стейк, накрыть оставшимися овощами.','Плотно завернуть фольгу и выложить свёртки на противень.','Запекать около 25 минут. Подавать прямо в фольге.']::text[], 'https://www.edimdoma.ru/retsepty/70506-semga-s-pomidorami-i-pertsem-zapechennaya-v-folge', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
