insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('mn-mintay-v-omlete', 'Минтай в омлете', 'Минтай с морковью под омлетом с сыром: рыба и яйца в одном блюде', 'main', array['lunch','dinner']::text[], 15, 55, 4, 2, 'fish', array['духовка','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Рыбу в его порции проверить на кости, перец только взрослым в тарелку.', array['Морковь и сыр натереть на крупной тёрке, зелень мелко порубить, филе нарезать кусками.','Взбить яйца, влить молоко, добавить зелень и соль и ещё раз перемешать.','Форму смазать маслом, выложить половину моркови, на неё рыбу, сверху остальную морковь.','Залить омлетной смесью и посыпать сыром.','Запекать при 180 °C 35–40 минут, пока омлет не схватится.']::text[], 'https://1000.menu/cooking/31557-ryba-v-omlete-v-duxovke', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
