insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-makarony', 'Макароны', 'Гарнир за 15 минут, который едят все', 'side', array['lunch','dinner']::text[], 5, 15, 4, 2, 'none', array['быстро','будни','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит как есть.', array['Вскипятить 3 литра воды и посолить.','Всыпать макароны и варить по инструкции на пачке, помешивая.','Откинуть на дуршлаг и перемешать со сливочным маслом.']::text[], null, null) on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
