insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-bulgur', 'Булгур', 'Рассыпчатый булгур — замена рису и гречке для разнообразия', 'side', array['lunch','dinner']::text[], 5, 25, 4, 3, 'none', array['быстро','будни']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит. Солить умеренно.', array['Растопить масло в кастрюле и обжарить в нём сухой булгур 2 минуты, помешивая.','Залить 500 мл кипятка, посолить.','Варить под крышкой на слабом огне 15 минут.','Снять с огня и дать постоять под крышкой 5 минут.']::text[], null, null) on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
