insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-ovoshchnoe-ragu', 'Овощное рагу', 'Кабачок, перец, морковь и помидоры, тушённые до мягкости', 'side', array['lunch','dinner']::text[], 20, 45, 4, 3, 'none', array['будни','постное']::text[], array['summer','autumn']::text[], '{}'::text[], 'adapt', 'Подходит. Его порцию отложить до чеснока и соли.', array['Лук нарезать, морковь натереть и обжарить на масле 5 минут.','Кабачок и перец нарезать кубиками, добавить к луку и тушить под крышкой 10 минут.','Помидоры нарезать, добавить к овощам, посолить.','Тушить ещё 15 минут до мягкости, в конце добавить рубленый чеснок.']::text[], null, null) on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
