insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('side-brokkoli', 'Брокколи и цветная капуста на пару', 'Капуста на пару за 15 минут; подойдёт и замороженная', 'side', array['lunch','dinner']::text[], 5, 20, 4, 2, 'none', array['быстро','будни']::text[], array['any']::text[], '{}'::text[], 'ok', 'Подходит как есть.', array['Капусту разобрать на соцветия.','Готовить на пару 10–12 минут, до мягкости.','Посолить и полить растопленным маслом.']::text[], null, null) on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
