insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-borshch', 'Борщ', 'Наваристый борщ на говяжьем бульоне, после настаивания ещё вкуснее', 'soup', array['lunch']::text[], 50, 150, 10, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию с капустой, картофелем и мясом, когда картофель сварится, — до зажарки и соли.', array['Половину лука и моркови подпечь целиком на сухой сковороде до тёмных пятен.','Говядину залить 3,75 л холодной воды, довести до кипения и снять пену. Положить подпечённые овощи и стебли зелени и варить на слабом огне 1–1,5 часа.','Бульон процедить, мясо снять с костей и нарезать.','Оставшиеся лук и морковь нарезать и обжарить на масле 5 минут. Добавить тёртую свёклу с уксусом, потом томатную пасту и тушить 10–15 минут.','В кипящий бульон положить нашинкованную капусту, после закипания — картофель кубиками. Варить 10 минут.','Переложить зажарку и мясо, варить ещё 5–7 минут до мягкости овощей.','Посолить, добавить сахар, лавровый лист, чеснок и рубленую зелень. Выключить и дать настояться под крышкой час. Подавать со сметаной.']::text[], 'https://www.gastronom.ru/recipe/4379/borshch-s-myasom-bazovyj-recept', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
