insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-shchi-svezhie', 'Щи из свежей капусты', 'Классические щи с говядиной, капустой и помидорами', 'soup', array['lunch']::text[], 40, 90, 12, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию с капустой, картофелем и мясом до зажарки, чеснока и соли.', array['Говядину залить 4 л холодной воды, довести до кипения и снять пену. Положить по половине лука и моркови целиком, лавровый лист и варить около часа.','Бульон процедить, мясо снять с кости и нарезать кубиками.','Капусту нашинковать, картофель нарезать кубиками, положить в кипящий бульон и варить 10 минут.','Пока варятся овощи, слегка обжарить на масле оставшийся лук, добавить морковь соломкой и тёртые помидоры. Тушить 7 минут.','Переложить зажарку и мясо в суп и варить 15 минут на слабом огне.','Чеснок растереть с солью и добавить в суп, поперчить, довести до кипения. Выключить и дать настояться 15 минут.']::text[], 'https://www.gastronom.ru/recipe/4001/shchi-iz-svezhej-kapusty', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
