insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-shchi-kislye', 'Щи из квашеной капусты', 'Кислые щи на говядине, капуста томится отдельно и становится мягкой', 'soup', array['lunch']::text[], 40, 150, 12, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию с картофелем, морковью и мясом до капусты, жареного лука и соли.', array['Говядину залить 3,6 л холодной воды, довести до кипения и снять пену. Положить одну луковицу и одну морковь целиком и варить на слабом огне 1,5–2 часа.','Квашеную капусту выложить в сковороду, влить 150 мл воды и тушить под крышкой 35–40 минут. Очень кислую капусту сначала промыть.','Мясо вынуть и нарезать, варёные овощи выбросить. В бульон положить картофель кубиками и натёртую морковь, варить 10 минут.','Оставшийся лук мелко нарезать и обжарить на масле до золотистого цвета.','Положить в суп капусту, мясо, жареный лук и лавровый лист. Варить 15–20 минут.','Посолить, поперчить, добавить чеснок и зелень. Выключить и дать настояться 15–20 минут.']::text[], 'https://1000.menu/cooking/20099-shchi-iz-kvashenoi-kapusty-s-govyadinoi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
