insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-rassolnik', 'Рассольник с перловкой', 'Рассольник на говяжьем бульоне с перловкой и солёными огурцами', 'soup', array['lunch']::text[], 40, 150, 10, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию с перловкой, картофелем и мясом до огурцов, рассола и соли.', array['Говядину залить водой, довести до кипения и через пару минут воду слить. Залить 3 л свежей воды, положить лавровый лист и варить 1–1,5 часа, снимая пену.','Пока варится мясо, промытую перловку залить кипятком на час.','Лук и морковь обжарить на масле 3–5 минут, добавить мелко нарезанные огурцы и тушить 10–15 минут. В конце вмешать томатную пасту и прогреть ещё 3 минуты.','Мясо вынуть и нарезать. В бульон всыпать перловку и варить 15 минут, затем положить картофель кубиками и варить ещё 20 минут.','Положить зажарку и мясо, влить рассол, проварить 3 минуты. Посолить и поперчить по вкусу.','Добавить чеснок и укроп, через минуту выключить. Дать настояться полчаса, подавать со сметаной.']::text[], 'https://menunedeli.ru/2012/02/kak-prigotovit-rassolnik-recept-s-foto/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
