insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-solyanka', 'Солянка мясная', 'Сборная солянка с колбасами, огурцами, оливками и лимоном', 'soup', array['lunch']::text[], 40, 150, 10, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'skip', 'Колбасы, копчёности и рассол малышу нельзя. Отлить ему говяжий бульон с мясом до колбас и огурцов и сварить в нём картофель с морковью.', array['Кости и говядину залить 2,5 л холодной воды, довести до кипения и снять пену. Положить морковь и одну луковицу целиком и варить на слабом огне 1,5 часа.','Оставшийся лук мелко нарезать и обжарить на сливочном масле. Всыпать муку, прогреть, добавить томатную пасту и потомить пару минут.','Мясо вынуть и нарезать, бульон процедить. Колбаски, варёную колбасу и огурцы нарезать кубиками.','В кипящий бульон положить мясо, колбасы, огурцы, оливки, зажарку, лавровый лист и перец. Варить 10 минут.','Посолить в самом конце и выжать сок половины лимона. Подавать с ломтиком лимона и сметаной.']::text[], 'https://www.gastronom.ru/recipe/12299/solyanka-sbornaya-myasnaya', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
