insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-uha', 'Уха из горбуши', 'Лёгкая уха из горбуши, чуть загущённая манкой', 'soup', array['lunch','dinner']::text[], 20, 50, 12, 3, 'fish', array['на 2–3 дня']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию до соли и перца, рыбу разобрать и проверить на кости.', array['Довести до кипения 3 л воды, положить нарезанные лук и картофель.','После закипания добавить нарезанную морковь и варить 15 минут на среднем огне.','Горбушу промыть, нарезать стейками, опустить в суп и варить 10 минут на слабом огне.','Добавить лавровый лист и сливочное масло. Тонкой струйкой всыпать манку, помешивая, и варить 5 минут.','Посолить, поперчить, всыпать рубленый укроп и выключить. Дать постоять 3 минуты.']::text[], 'https://www.gastronom.ru/recipe/56279/uha-iz-gorbushi', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
