insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-gorohovyi', 'Гороховый суп', 'Густой гороховый суп на свиных рёбрах', 'soup', array['lunch']::text[], 30, 120, 12, 3, 'legume', array['на 2–3 дня','бюджетное','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Горох хорошо разварить. Отлить порцию до зажарки, соли и перца, мясо снять с рёбер и мелко порезать. Бобовые — не чаще 2–3 раз в неделю.', array['Горох промыть. Если есть время, замочить с вечера — сварится быстрее.','Рёбра разрезать по одному, залить 3,5 л воды, довести до кипения и снять пену. Всыпать горох и варить на слабом огне около часа, пока он не разварится.','Лук и морковь нарезать кубиками и обжарить на масле до золотистого цвета.','Положить в суп картофель кубиками, через 10 минут — зажарку и лавровый лист. Варить до мягкости картофеля.','Посолить, поперчить, посыпать петрушкой и дать настояться 10 минут.']::text[], 'https://eda.rambler.ru/recepty/supy/gorohovij-sup-s-rebrishkami-43793', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
