insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-kurinyi-s-lapshoi', 'Куриный суп с лапшой', 'Прозрачный куриный бульон с лапшой и яйцом, без зажарки', 'soup', array['lunch','dinner']::text[], 20, 80, 12, 3, 'poultry', array['на 2–3 дня','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'ok', 'Курицу и яйцо мелко порезать.', array['Курицу залить 4 л холодной воды, довести до кипения, снять пену и варить на слабом огне около часа.','Курицу вынуть, мясо снять с костей и нарезать. Бульон при желании процедить.','В кипящий бульон положить картофель соломкой и варить 7–10 минут.','Всыпать лапшу, варить 2–3 минуты и выключить. Посолить по вкусу. Если суп на несколько дней, лапшу лучше варить порциями перед подачей, иначе разбухнет.','Яйца сварить вкрутую и порубить. В тарелку положить курицу и яйцо и залить супом.']::text[], 'https://www.iamcook.ru/showrecipe/35247', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
