insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-frikadelki', 'Суп с фрикадельками', 'Картофельный суп с мясными фрикадельками, без долгого бульона', 'soup', array['lunch']::text[], 30, 50, 10, 3, 'red-meat', array['на 2–3 дня','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Слепить ему несколько фрикаделек из фарша без чеснока и перца и сварить со всеми. Порцию отлить до зажарки и соли.', array['Половину лука мелко нарезать для зажарки, вторую измельчить блендером с ложкой воды.','Смешать фарш с измельчённым луком, сухарями и яйцом. Отложить Диме 3–4 ложки, в остальное добавить чеснок, соль и перец. Слепить фрикадельки размером с грецкий орех.','Картофель нарезать кубиками, морковь натереть.','Лук с морковью обжарить на масле на среднем огне до полуготовности.','Фрикадельки опустить в 3 л кипящей воды и после закипания снять пену.','Добавить картофель, зажарку и лавровый лист, накрыть крышкой и варить на маленьком огне 12–15 минут.','Посолить, всыпать зелень, довести до кипения и дать настояться под крышкой 10 минут. Подавать со сметаной.']::text[], 'https://menunedeli.ru/recipe/sup-s-frikadelkami-klassicheskij/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
