insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-klyotski', 'Суп с клёцками', 'Куриный суп с мягкими клёцками из заварного теста', 'soup', array['lunch','dinner']::text[], 40, 80, 10, 3, 'poultry', array['на 2–3 дня','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию с курицей и клёцками до зажарки и соли.', array['Курицу залить 4 л холодной воды, довести до кипения на сильном огне и снять пену.','Половину лука и моркови подпечь целиком на сухой сковороде, положить в бульон с лавровым листом и варить на слабом огне 40 минут.','Курицу вынуть, мясо снять и нарезать, кости вернуть в бульон ещё на 15 минут. Бульон процедить.','Для клёцек смешать яйца, щепотку соли, половину муки и 4 ч. л. масла. Влить 12 ст. л. горячего бульона, вмешать остальную муку и оставить на 15 минут.','Тесто набирать чайной ложкой, смоченной в бульоне, и опускать в кипящий бульон. Варить, пока клёцки не всплывут.','Оставшиеся лук и морковь мелко нарезать и натереть, обжарить на масле 5 минут и переложить в суп. Варить 3 минуты.','Вернуть мясо, прогреть, посолить и поперчить. Подавать с петрушкой.']::text[], 'https://www.gastronom.ru/recipe/59489/sup-s-kleckami-na-kurinom-bulone', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
