insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-tykva-pyure', 'Суп-пюре из тыквы', 'Нежный суп-пюре из тыквы со сливками за 40 минут', 'soup', array['lunch','dinner']::text[], 20, 40, 12, 3, 'none', array['на 2–3 дня','будни']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Отложить порцию пюре до соли и перца.', array['Лук нарезать и обжарить на масле в кастрюле 7–8 минут до золотистого цвета. Добавить измельчённый чеснок и готовить ещё минуту.','Положить тыкву кусочками и прогреть 2–3 минуты, помешивая.','Залить 1,3 л воды или бульона, довести до кипения и варить 15–20 минут, пока тыква не станет мягкой.','Снять с огня и пробить погружным блендером до гладкости.','Влить сливки, посолить и поперчить, прогреть, не доводя до кипения.']::text[], 'https://www.iamcook.ru/showrecipe/13040', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
