insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-brokkoli-pyure', 'Суп-пюре из брокколи и цветной капусты', 'Зелёный суп-пюре из брокколи и цветной капусты с сыром', 'soup', array['lunch','dinner']::text[], 15, 40, 12, 3, 'dairy', array['на 2–3 дня','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию пюре до сыра и соли.', array['Лук, картофель и чеснок мелко нарезать. В кастрюле с толстым дном растопить сливочное масло вместе с растительным.','Обжарить овощи, помешивая, пока лук не станет мягким.','Добавить соцветия брокколи и цветной капусты, залить 1,5 л бульона или кипятка и варить 15–20 минут до мягкости.','Снять с огня, влить молоко, всыпать тёртый сыр и пробить блендером. Если густо, добавить ещё молока.','Посолить по вкусу и подавать.']::text[], 'https://www.iamcook.ru/showrecipe/9854', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
