insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-syrnyi-s-kuritsei', 'Сырный суп с курицей', 'Сливочный суп с курицей и плавленым сыром за 45 минут', 'soup', array['lunch']::text[], 20, 45, 10, 3, 'poultry', array['на 2–3 дня','будни','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Плавленый сыр малышу нельзя. Отлить ему порцию с курицей и картофелем до зажарки, сыра и соли.', array['Филе залить 3,7 л холодной воды, довести до кипения, снять пену и варить 20–30 минут.','Курицу вынуть, нарезать кусочками и вернуть в бульон. Положить картофель кубиками и варить 15 минут.','Лук и тёртую морковь обжарить на масле и переложить в суп.','Раскрошить плавленый сыр и мешать, пока он не разойдётся, около 5 минут.','Всыпать вермишель и варить ещё 5 минут. Посолить, поперчить, добавить чеснок и укроп.']::text[], 'https://www.edimdoma.ru/retsepty/142095-syrnyy-sup-s-kuritsey', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
