insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-chechevichnyi', 'Чечевичный суп', 'Постный суп из красной чечевицы с картофелем, без зажарки', 'soup', array['lunch']::text[], 10, 45, 12, 3, 'legume', array['на 2–3 дня','постное','бюджетное','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию до соли и перца, чечевица должна хорошо развариться. Бобовые — не чаще 2–3 раз в неделю.', array['Чечевицу промыть до чистой воды. Можно замочить на 2 часа и промыть ещё раз.','Залить 2,5 л воды, довести до кипения и варить 20 минут на среднем огне.','Добавить картофель кубиками и натёртую морковь, варить ещё 20 минут до мягкости.','За 5 минут до конца посолить и поперчить.','Снять с огня и дать постоять под крышкой 10 минут.']::text[], 'https://1000.menu/cooking/40179-sup-s-chechevicei-i-kartofelem', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
