insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-fasolevyi', 'Фасолевый суп', 'Быстрый постный суп из консервированной фасоли с томатами', 'soup', array['lunch']::text[], 15, 30, 12, 3, 'legume', array['на 2–3 дня','постное','бюджетное','быстро']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию до зажарки, соли и перца, фасоль размять вилкой. Бобовые — не чаще 2–3 раз в неделю.', array['Картофель нарезать мелким кубиком, опустить в 2,5 л кипящей воды и варить 10 минут.','Добавить фасоль вместе с жидкостью из банки и варить 10–15 минут до готовности картофеля.','Лук мелко нарезать, морковь натереть и обжарить на масле 5–7 минут.','Добавить измельчённые томаты, тушить ещё 10 минут и переложить в суп.','Посолить, поперчить, всыпать петрушку и дать настояться 10 минут.']::text[], 'https://www.iamcook.ru/showrecipe/11520', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
