insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-harcho', 'Харчо', 'Пряный грузинский суп с говядиной, рисом и орехами', 'soup', array['lunch']::text[], 40, 150, 10, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию с рисом и мясом до зажарки, орехов, специй, чеснока и острого перца.', array['Говядину нарезать, залить 3,7 л холодной воды и варить около 1,5 часа, снимая пену.','Мясо снять с кости и нарезать, бульон процедить.','В кипящий бульон всыпать промытый рис, положить мясо, посолить и варить 10 минут. Вмешать томатную пасту.','Лук мелко нарезать, обжарить на масле, присыпать мукой и прогреть пару минут. Переложить в суп вместе с лавровым листом.','Орехи измельчить блендером, смешать с хмели-сунели и гранатовым соком, влить в суп и прогреть на слабом огне.','Кинзу, чеснок и острый перец мелко порубить, добавить в снятый с огня суп с базиликом. Накрыть и дать настояться 10 минут.']::text[], 'https://www.gastronom.ru/recipe/4632/sup-harcho-iz-govjadiny-s-risom', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
