insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-risovyi-s-kuritsei', 'Рисовый суп с курицей', 'Простой суп на курином бульоне с рисом и картошкой', 'soup', array['lunch']::text[], 20, 60, 12, 3, 'poultry', array['на 2–3 дня','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию с рисом, картофелем и курицей до зажарки и соли.', array['Бёдра и целую луковицу залить 3,7 л холодной воды, довести до кипения, снять пену и варить 25 минут.','Картофель нарезать, рис промыть до прозрачной воды.','Лук и курицу вынуть. В бульон положить картофель и рис и варить 15 минут.','Морковь натереть и обжарить на масле около 10 минут.','Мясо снять с костей без кожи и разобрать на волокна.','Положить в суп зажарку, мясо и паприку, посолить и варить 5 минут. Дать настояться под крышкой.']::text[], 'https://1000.menu/cooking/32963-sup-risovyi-s-kuricei-i-kartoshkoi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
