insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-mintai', 'Суп из минтая', 'Недорогой рыбный суп из минтая с томатной зажаркой', 'soup', array['lunch']::text[], 25, 45, 12, 3, 'fish', array['на 2–3 дня','бюджетное','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию бульона с картофелем до зажарки и соли, рыбу ещё раз проверить на кости.', array['Минтай заранее разморозить в холодильнике, около 8 часов. Промыть и нарезать крупными кусками.','Рыбу залить 4 л воды, довести до кипения и снять пену. Добавить лавровый лист и перец горошком и варить 20 минут на слабом огне.','Бульон процедить, мякоть отделить от костей и отложить, залив парой ложек бульона.','Картофель нарезать ломтиками и варить в бульоне 10 минут.','Лук, тёртую морковь и чеснок обжарить на масле, добавить томатную пасту и 3–4 ст. л. бульона, тушить 5 минут. Переложить в суп и варить 5 минут.','Посолить, поперчить и дать настояться 10–15 минут. Рыбу разложить по тарелкам, залить супом и посыпать зеленью.']::text[], 'https://www.gastronom.ru/recipe/60162/rybnyj-sup-iz-mintaya-s-kartofelem', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
