insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-iz-konservov', 'Суп из рыбных консервов', 'Суп из сайры с рисом за полчаса, без варки бульона', 'soup', array['lunch']::text[], 10, 30, 10, 3, 'fish', array['на 2–3 дня','бюджетное','быстро']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию до сайры, соли, перца и чеснока. Добавить в неё размятую сайру без хребта.', array['Картофель нарезать кубиками, морковь натереть, лук и чеснок мелко нарезать. Рис промыть в нескольких водах.','Картофель опустить в 3,4 л кипящей воды и варить 10 минут.','Добавить морковь и лук, через 5 минут — рис, и варить ещё 10 минут.','Положить лавровый лист, соль, перец, чеснок и сайру вместе с жидкостью, довести до кипения.','Снять с огня, всыпать укроп и дать настояться под крышкой 5 минут.']::text[], 'https://www.edimdoma.ru/retsepty/154486-rybnyy-sup-iz-konservov-s-risom', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
