insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-ovoshchnoi', 'Овощной суп', 'Постный суп из кабачка, капусты и сладкого перца', 'soup', array['lunch','dinner']::text[], 20, 45, 10, 3, 'none', array['на 2–3 дня','постное','бюджетное','будни']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию до соли и перца.', array['Лук нарезать кубиком, морковь полукольцами, картофель мелким кубиком и опустить в 2,5 л кипящей воды на 5 минут.','Добавить нашинкованную капусту и болгарский перец кубиками.','Через 5 минут положить кабачок и помидор кубиками и варить 5–10 минут до мягкости.','Добавить горошек без жидкости и лавровый лист, посолить, поперчить и варить ещё 5 минут.','Снять с огня и дать настояться не меньше 15 минут. Подавать с зеленью, по желанию со сметаной.']::text[], 'https://www.iamcook.ru/showrecipe/17495', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
