insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-okroshka', 'Окрошка на кефире', 'Окрошка с курицей на кефире; основу и заливку хранить отдельно', 'soup', array['lunch','dinner']::text[], 30, 80, 10, 2, 'poultry', array['на 2–3 дня']::text[], array['summer']::text[], '{}'::text[], 'adapt', 'Редис малышу нельзя. Отложить ему основу до редиса, нарезать мельче и залить кефиром без соли и перца.', array['Куриное филе сварить в подсоленной воде с чесноком на слабом огне до готовности, около 40 минут. Остудить.','Картофель отварить в мундире, яйца — вкрутую 10 минут. Остудить и очистить.','Курицу, картофель, яйца и огурцы нарезать кубиками, редис натереть на крупной тёрке, зелень мелко порубить. Перемешать — это основа.','Основу и кефир хранить в холодильнике отдельно, не дольше двух дней.','Перед подачей разложить основу по тарелкам, залить холодным кефиром, посолить и поперчить.']::text[], 'https://www.gastronom.ru/recipe/57185/okroshka-s-kuricej-na-kefire', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
