insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-svekolnik', 'Свекольник холодный', 'Холодный летний суп на свекольном отваре с огурцом и яйцом', 'soup', array['lunch','dinner']::text[], 25, 150, 10, 2, 'egg', array['на 2–3 дня','бюджетное']::text[], array['summer']::text[], '{}'::text[], 'adapt', 'Сметану ему без горчицы, свёклу и огурец порезать мельче.', array['Свёклу очистить и нарезать тонкой соломкой.','Вскипятить 2,5 л воды с солью, лимонным соком и сахаром, положить свёклу, накрыть и варить на слабом огне 20 минут. Полностью остудить.','Огурцы нарезать соломкой, укроп и зелёный лук мелко порубить. Это основа.','Основу и свекольный отвар хранить в холодильнике отдельно, не дольше двух дней.','Яйца сварить вкрутую и разрезать пополам. Сметану для взрослых можно смешать с горчицей.','Перед подачей разложить основу по тарелкам, залить холодным отваром со свёклой, добавить яйцо и сметану.']::text[], 'https://www.gastronom.ru/recipe/21743/klassicheskij-holodnyj-svekolnik', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
