insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-shchavelevyi', 'Щавелевый суп', 'Весенний кисленький суп со щавелем и яйцом за полчаса', 'soup', array['lunch']::text[], 15, 30, 10, 3, 'egg', array['на 2–3 дня','бюджетное','быстро']::text[], array['spring','summer']::text[], '{}'::text[], 'adapt', 'Отлить порцию до зажарки и соли.', array['Картофель нарезать брусочками, залить 2,5 л воды и поставить на огонь. После закипания снять пену.','Морковь натереть, лук мелко нарезать и обжарить на масле 5 минут.','Через 5–7 минут после закипания положить зажарку в суп, убавить огонь и варить 10 минут.','Щавель перебрать, оборвать стебли, листья нарезать, положить в суп и варить 3–4 минуты.','Яйца взбить вилкой и тонкой струйкой влить в суп, помешивая. Посолить и варить 2 минуты. Подавать со сметаной.']::text[], 'https://www.iamcook.ru/showrecipe/822', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
