insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sp-kartofelnyi-s-govyadinoi', 'Картофельный суп с говядиной', 'Простой суп с говядиной и картошкой, без капусты и круп', 'soup', array['lunch']::text[], 30, 120, 10, 3, 'red-meat', array['на 2–3 дня','выходные']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отлить порцию с картофелем и мясом до зажарки, соли и перца, мясо мелко порезать.', array['Мясо промыть, нарезать порциями, сложить в кастрюлю с лавровым листом, залить 4 л воды и довести до кипения.','Снять пену, убавить огонь и варить 1–1,5 часа до мягкости мяса.','Лук мелко нарезать и обжарить на масле, добавить тёртую морковь и готовить 8–10 минут на небольшом огне.','Положить в бульон картофель кубиками и варить 10–15 минут.','Добавить зажарку и после закипания варить 4–5 минут. Всыпать петрушку, посолить и поперчить.','Выключить и дать настояться под крышкой 10–15 минут.']::text[], 'https://menunedeli.ru/recipe/klassicheskij-sup-s-myasom-i-kartoshkoj/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
