insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-vinegret', 'Винегрет', 'Постный салат из варёных овощей с квашеной капустой', 'salad', array['lunch','dinner']::text[], 20, 70, 6, 2, 'none', array['постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему варёные свёклу, морковь, картофель и горошек до капусты, огурцов и лука, заправить маслом без соли.', array['Свёклу, морковь и картофель сварить в кожуре до мягкости, слить воду и остудить.','Квашеную капусту отжать от рассола, горошек откинуть на сито, зелень мелко порубить.','Овощи очистить и вместе с огурцами и луком нарезать кубиками.','Свёклу сначала перемешать с ложкой масла, чтобы меньше красила остальное.','Сложить всё в салатник, полить оставшимся маслом, посолить по вкусу и перемешать.']::text[], 'https://1000.menu/cooking/25387-vinegret-variant-klassicheskogo', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
