insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-olivie-s-kuritsei', 'Оливье с курицей', 'Оливье с отварной курицей вместо колбасы', 'salad', array['lunch','dinner']::text[], 30, 70, 6, 1, 'poultry', array['праздничное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Майонез нельзя. Отложить ему порцию без лука и огурцов и заправить сметаной.', array['Куриное филе сварить в подсоленной воде до готовности и остудить.','Картофель сварить в кожуре до мягкости, яйца — вкрутую 10 минут. Остудить и очистить.','Курицу, картофель, яйца, огурцы и лук нарезать одинаковым мелким кубиком.','Смешать с горошком без жидкости.','Заправить майонезом, посолить и поперчить. Если салат на два дня, заправлять порциями перед подачей.']::text[], 'https://www.gastronom.ru/recipe/2690/salat-olive-s-kuricej', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
