insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-kapusta-s-morkovyu', 'Капуста с морковью', 'Хрустящая капуста с морковью и уксусом, как в столовой', 'salad', array['lunch','dinner']::text[], 20, 140, 4, 3, 'none', array['постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Уксус нельзя. Отложить ему капусту с морковью до уксуса, нарезать мельче и заправить маслом.', array['Капусту тонко нашинковать, посолить и помять руками, пока не пустит сок. Оставить на 10 минут.','Подогреть капусту на водяной бане или в микроволновке до тёплой, не тушить.','Влить уксус и перемешать.','Добавить натёртую морковь и сахар, убрать в холодильник на 1–1,5 часа.','Перед подачей слегка отжать лишний сок и заправить маслом.']::text[], 'https://www.gastronom.ru/recipe/60811/salat-iz-svezhej-kapusty-i-morkovi-kak-v-stolovoj', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
