insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-ogurtsy-pomidory', 'Огурцы и помидоры со сметаной', 'Летний салат за 10 минут со сметаной и укропом', 'salad', array['lunch','dinner']::text[], 10, 10, 4, 1, 'none', array['быстро','без плиты']::text[], array['summer','autumn']::text[], '{}'::text[], 'ok', 'Нарезать мельче.', array['Огурцы нарезать полукольцами, помидоры дольками, укроп мелко порубить.','Огурцы сложить в миску, посыпать укропом и слегка посолить.','Добавить помидоры и заправить сметаной прямо перед подачей.','Дать постоять 5 минут и подавать.']::text[], 'https://1000.menu/cooking/7736-salat-iz-ogurtsov-i-pomidorov', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
