insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-svyokla-s-chesnokom', 'Свёкла с чесноком и сметаной', 'Тёртая варёная свёкла с чесноком, зелёным луком и сметаной', 'salad', array['lunch','dinner']::text[], 10, 90, 4, 2, 'none', array['бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему тёртую свёклу со сметаной до чеснока и лука.', array['Свёклу отварить или запечь до мягкости, остудить и очистить. Можно взять готовую варёную.','Натереть свёклу на крупной тёрке.','Зелёный лук мелко нарезать, чеснок измельчить.','Смешать свёклу с луком и чесноком, слегка посолить и заправить сметаной.','Убрать в холодильник на час, чтобы салат пропитался.']::text[], 'https://iamcook.ru/showrecipe/42340', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
