insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-morkov-s-yablokom', 'Морковь с яблоком', 'Сладковатый тёртый салат с изюмом и сметаной', 'salad', array['lunch','dinner']::text[], 10, 20, 4, 1, 'none', array['быстро','без плиты','детское','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Натереть на мелкой тёрке и порубить изюм, сахар можно не добавлять.', array['Изюм промыть и залить кипятком на 10 минут, затем слить воду и обсушить.','Морковь и яблоко очистить и натереть на крупной тёрке.','Смешать морковь, яблоко и изюм.','Заправить сметаной, посыпать сахаром и перемешать.']::text[], 'https://eda.rambler.ru/recepty/salaty/salat-iz-morkovi-s-yablokom-54072', 'eda.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
