insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-grecheskii', 'Греческий салат', 'Помидоры, огурец, брынза и оливки с оливковым маслом', 'salad', array['lunch','dinner']::text[], 15, 30, 4, 1, 'dairy', array['быстро']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему помидоры, огурец и немного брынзы без лука и уксусной заправки, полить маслом. Оливки разрезать на мелкие кусочки.', array['Лук нарезать тонкими полукольцами и залить смесью уксуса и оливкового масла на 20 минут.','Помидоры нарезать кубиками, посыпать сахаром и щепоткой соли и оставить на 10 минут.','Огурец и брынзу нарезать кубиками, из оливок вынуть косточки, если есть.','Разложить на блюде огурец, помидоры, лук, оливки и брынзу.','Посолить, поперчить, посыпать орегано и полить оставшейся заправкой.']::text[], 'https://www.gastronom.ru/recipe/31799/grecheskij-salat-recept-s-brynzoj', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
