insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-tsezar-s-kuritsei', 'Цезарь с курицей', 'Цезарь с жареной курицей, сухариками и домашним сырным соусом', 'salad', array['lunch','dinner']::text[], 35, 60, 4, 1, 'poultry', '{}'::text[], array['any']::text[], '{}'::text[], 'adapt', 'Курицу ему отварить или запечь, а не жарить. Дать листья, черри четвертинками и курицу без соуса и сухариков.', array['Хлеб нарезать кубиками, перемешать с ложкой масла и измельчённым зубчиком чеснока и подсушить в духовке до золотистого цвета.','Куриное филе посолить, поперчить и обжарить на среднем огне до готовности. Остудить и нарезать.','Яйца сварить вкрутую.','Для соуса пробить блендером одно яйцо, половину тёртого сыра, лимонный сок, оставшийся чеснок, горчицу и масло.','Листья салата порвать руками, черри разрезать пополам, оставшийся сыр нарезать тонкими пластинками.','Выложить листья, курицу, черри и сыр, полить соусом, сверху положить сухарики и половинки второго яйца.']::text[], 'https://1000.menu/cooking/52359-salat-cezar-s-kuricei-i-sousom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
