insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-krabovyi', 'Крабовый салат', 'Крабовые палочки, рис, кукуруза и яйцо под майонезом', 'salad', array['lunch','dinner']::text[], 20, 40, 4, 1, 'egg', array['праздничное']::text[], array['any']::text[], '{}'::text[], 'skip', 'Крабовые палочки и майонез малышу нельзя. Дать ему рис с яйцом и кукурузой, заправленные сметаной.', array['Рис промыть до прозрачной воды, всыпать в 200 мл кипящей подсоленной воды и варить на маленьком огне 15 минут. Остудить.','Яйца сварить вкрутую 10 минут, охладить и мелко порубить.','Крабовые палочки нарезать кубиками, зелёный лук — колечками, кукурузу откинуть на сито.','Смешать всё с майонезом, посолить и поперчить по вкусу.']::text[], 'https://www.gastronom.ru/recipe/31228/salat-s-risom-kukuruzoi-i-krabovymi-palochkami', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
