insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-mimoza', 'Мимоза', 'Слоёный салат из сайры с яйцом, картошкой и морковью', 'salad', array['lunch','dinner']::text[], 30, 120, 6, 1, 'fish', array['праздничное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Майонез и сырой лук нельзя. Собрать ему порцию отдельно: картофель, морковь, яйцо и сайра без хребта со сметаной.', array['Картофель и морковь сварить в кожуре, яйца — вкрутую. Остудить и очистить.','Из сайры слить жидкость, рыбу размять вилкой и выложить первым слоем, сверху — мелко нарезанный лук.','Нанести сеточку майонеза, натереть сверху картофель и снова смазать майонезом.','Натереть морковь, смазать майонезом, затем натереть белки.','Сверху натереть желтки, по краю посыпать рубленым укропом.','Убрать в холодильник на пару часов, чтобы слои пропитались.']::text[], 'https://1000.menu/cooking/21439-salat-mimoza-s-sairoi-klassicheskii', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
