insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-shuba', 'Селёдка под шубой', 'Сельдь под слоями печёных овощей и майонеза', 'salad', array['lunch','dinner']::text[], 40, 240, 6, 1, 'fish', array['праздничное','духовка','выходные']::text[], array['any']::text[], '{}'::text[], 'skip', 'Солёную сельдь и майонез малышу нельзя. Дать ему печёные свёклу, морковь и картофель с яйцом и сметаной.', array['Морковь, свёклу и картофель по отдельности завернуть в фольгу и запекать при 190 °C 50 минут. Остудить.','Овощи очистить, натереть на крупной тёрке и каждый по отдельности смешать с частью майонеза, посолить и поперчить.','Лук мелко нарезать и обдать кипятком. Сельдь нарезать мелкими кубиками, выбирая косточки.','Выложить слоями: лук, сельдь, картофель, морковь, свёкла.','Сверху натереть варёные яйца, накрыть плёнкой и охладить 2 часа. Украсить зелёным луком.']::text[], 'https://www.gastronom.ru/recipe/31490/seledka-pod-shuboj-klassicheskij-recept', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
