insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-fasol-s-suharikami', 'Салат с фасолью и сухариками', 'Красная фасоль с огурцом и сухариками под сметаной', 'salad', array['lunch','dinner']::text[], 10, 25, 4, 1, 'legume', array['быстро','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Фасоль размять вилкой, сухарики не давать. Бобовые — не чаще 2–3 раз в неделю.', array['Хлеб нарезать кубиками и подсушить в духовке при 180 °C 10–15 минут.','Фасоль откинуть на дуршлаг, промыть и дать стечь.','Огурец нарезать брусочками, укроп мелко порубить.','Смешать фасоль, огурец и укроп, посолить и заправить сметаной.','Сухарики добавить прямо перед подачей, чтобы не размокли.']::text[], 'https://1000.menu/cooking/38073-salat-s-krasnoi-konservirovannoi-fasolu-i-suxarikami', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
