insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-redis-ogurets-yaitso', 'Редис с огурцом и яйцом', 'Весенний салат с редисом, яйцом и соусом из желтков и сметаны', 'salad', array['lunch','dinner']::text[], 15, 20, 4, 1, 'egg', array['быстро']::text[], array['spring','summer']::text[], '{}'::text[], 'adapt', 'Редис, горчицу и малосольный огурец нельзя. Отложить ему свежий огурец с яйцом и сметаной.', array['Яйца сварить вкрутую, остудить и разделить на белки и желтки.','Редис нарезать кружочками, огурцы — ломтиками, зелёный лук — колечками, белки — ломтиками.','Желтки растереть вилкой с горчицей, добавить лук и холодную сметану, посолить и поперчить.','Сложить огурцы, редис и белки в салатник, заправить соусом и перемешать.','Подавать сразу: через 15 минут салат пустит сок.']::text[], 'https://www.gastronom.ru/recipe/4899/salat-iz-redisa-ogurca-i-yajca', 'gastronom.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
