insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-teplyi-s-kuritsei', 'Тёплый салат с курицей', 'Курица с обжаренными овощами на листьях салата', 'salad', array['dinner','lunch']::text[], 25, 30, 4, 1, 'poultry', array['быстро']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Соевый соус и чёрный перец ему нельзя. Его курицу потушить под крышкой с болгарским перцем и черри, без поджаривания; черри разрезать на четвертинки.', array['Курицу и болгарский перец нарезать полосками, черри разрезать пополам, лук — полукольцами. Листья салата промыть и обсушить.','Курицу обжарить на ложке масла 5–7 минут, посолить, поперчить, переложить на тарелку и накрыть.','На оставшемся масле обжарить лук 2–3 минуты, добавить перец на 5 минут, затем черри ещё на 2 минуты.','Выложить листья на тарелки, сверху курицу и овощи.','Полить соевым соусом и лимонным соком и сразу подавать.']::text[], 'https://www.edimdoma.ru/retsepty/153488-teplyy-salat-s-kuritsey-i-ovoschami', 'edimdoma.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
