insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-pekinskaya-s-kukuruzoi', 'Пекинская капуста с кукурузой', 'Хрустящая пекинская капуста с кукурузой, огурцом и яйцом', 'salad', array['lunch','dinner']::text[], 15, 20, 4, 1, 'egg', array['быстро','бюджетное','детское']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию до соли и перца.', array['Яйца сварить вкрутую, остудить и очистить.','Пекинскую капусту тонко нашинковать, огурец нарезать соломкой.','Зелень порубить, яйца нарезать соломкой, кукурузу откинуть на сито.','Сложить всё в салатник, посолить, поперчить и заправить маслом.']::text[], 'https://www.iamcook.ru/showrecipe/25517', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
