insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-vitaminnyi', 'Витаминный салат', 'Свежая капуста, морковь, яблоко и перец с лимонной заправкой', 'salad', array['lunch','dinner']::text[], 15, 15, 4, 1, 'none', array['быстро','без плиты','постное','бюджетное']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить порцию до лука, капусту и морковь натереть мельче.', array['Капусту тонко нашинковать и слегка помять руками.','Морковь натереть на средней тёрке, яблоко — на крупной и сразу сбрызнуть лимонным соком.','Лук и болгарский перец нарезать тонкой соломкой.','Сложить всё в салатник и заправить маслом и оставшимся лимонным соком.','Добавить соль, сахар и рубленый укроп, перемешать.']::text[], 'https://1000.menu/cooking/2839-salat-vitaminnyi-iz-kapusty-yablok-i-morkovi', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
