insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-tunets-s-yaitsom', 'Салат с тунцом и яйцом', 'Слоёный салат из тунца, огурца и яиц', 'salad', array['lunch','dinner']::text[], 15, 25, 4, 1, 'fish', array['быстро']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Майонез нельзя. Собрать ему порцию со сметаной.', array['Яйца сварить вкрутую, остудить и очистить.','Из тунца слить жидкость, убрать кости и разобрать рыбу вилкой.','Огурец нарезать мелким кубиком, немного оставить кружочками для украшения.','Белки мелко порубить, желтки натереть на мелкой тёрке.','Выложить слоями огурец, тунец и белки, смазывая каждый слой майонезом, сверху посыпать желтками.','Украсить огурцом и петрушкой. Подать сразу или дать постоять час в холодильнике.']::text[], 'https://1000.menu/cooking/13158-salat-s-tuncom-ogurcom-yaicom', '1000.menu') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
