insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-svyokla-s-chernoslivom', 'Свёкла с черносливом и орехами', 'Печёная свёкла с черносливом, грецкими орехами и чесноком', 'salad', array['lunch','dinner']::text[], 15, 80, 4, 2, 'none', array['духовка']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Майонез, чеснок и кусочки орехов нельзя. Отложить ему тёртую свёклу с мелко порезанным черносливом и сметаной.', array['Свёклу завернуть в фольгу и запечь при 180 °C около 40 минут до мягкости. Остудить и очистить.','Чернослив залить горячей водой на 15 минут, обсушить и нарезать.','Орехи порубить ножом, свёклу натереть на крупной тёрке.','Чеснок натереть на мелкой тёрке и смешать с майонезом.','Соединить свёклу, чернослив, орехи и соус. Подать сразу или дать постоять пару часов в холодильнике.']::text[], 'https://menunedeli.ru/recipe/salat-iz-svekly-s-chernoslivom-i-greckim-orexom/', 'menunedeli.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
