insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-struchkovaya-fasol', 'Стручковая фасоль с яйцом', 'Стручковая фасоль с яйцом, сыром и сметаной за 20 минут', 'salad', array['lunch','dinner']::text[], 15, 20, 4, 1, 'egg', array['быстро']::text[], array['any']::text[], '{}'::text[], 'adapt', 'Отложить ему фасоль с яйцом и сыром до чеснока, оливок и перца, заправить сметаной, стручки мелко порезать.', array['Фасоль опустить в слегка подсоленный кипяток на 3 минуты, слить воду и остудить.','Яйца сварить вкрутую и нарезать кубиками, сыр натереть на крупной тёрке.','Чеснок измельчить, оливки нарезать колечками, укроп порубить.','Соединить всё, заправить сметаной, посолить и поперчить. Подавать сразу.']::text[], 'https://www.iamcook.ru/showrecipe/3454', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
