insert into public.recipes (id, name, about, category, meals, time_active, time_total, servings, keeps_days, protein, tags, season, collections, dima_level, dima_note, steps, source_url, source_site) values ('sl-kvashenaya-kapusta-s-lukom', 'Квашеная капуста с луком', 'Квашеная капуста с маринованным луком и растительным маслом', 'salad', array['lunch','dinner']::text[], 10, 35, 4, 2, 'none', array['постное','бюджетное']::text[], array['autumn','winter']::text[], '{}'::text[], 'adapt', 'Маринованный лук нельзя. Дать ему немного капусты без лука, промыв её от рассола.', array['Лук нарезать тонкими полосками.','Нагреть 320 мл воды почти до кипения, растворить сахар и соль, влить уксус и положить лавровый лист.','Залить лук горячим маринадом на 25–30 минут, затем откинуть на сито.','Капусту откинуть на дуршлаг, чтобы стёк сок, длинные полоски нарезать короче.','Смешать капусту с луком и заправить маслом.']::text[], 'https://www.iamcook.ru/showrecipe/41352', 'iamcook.ru') on conflict (id) do update set name = excluded.name, about = excluded.about, category = excluded.category, meals = excluded.meals, time_active = excluded.time_active, time_total = excluded.time_total, servings = excluded.servings, keeps_days = excluded.keeps_days, protein = excluded.protein, tags = excluded.tags, season = excluded.season, collections = excluded.collections, dima_level = excluded.dima_level, dima_note = excluded.dima_note, steps = excluded.steps, source_url = excluded.source_url, source_site = excluded.source_site, updated_at = now();
